values
  ('ancestry.human', 'Humano', 'Human', 'Humano', 'Ancestralidade versátil, com escolhas flexíveis de atributos e talentos.', 'A versatile ancestry with flexible attribute and feat choices.', 'Una ascendencia versátil, con elecciones flexibles de atributos y dotes.', 8, 'Médio', 25, ARRAY['Livre', 'Livre']::text[], NULL, ARRAY['Comum', '1 idioma adicional']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 62, '{"senses":[],"heritagesList":["Humano Versátil (Talento Geral extra)","Humano Habilidoso (Perícia extra)","Meio-Elfo (Aelfin)","Meio-Orc (Dromaar)","Humano Herdeiro do Inverno"],"needs_review":false}'::jsonb),
  ('ancestry.dwarf', 'Anão', 'Dwarf', 'Enano', 'Ancestralidade resistente, com 10 PV e forte tradição comunitária.', 'A resilient ancestry with 10 HP and strong community traditions.', 'Una ascendencia resistente, con 10 PG y fuertes tradiciones comunitarias.', 10, 'Médio', 20, ARRAY['Constituição', 'Sabedoria', 'Livre']::text[], 'Carisma', ARRAY['Comum', 'Anão']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 42, '{"senses":["Visão no Escuro"],"heritagesList":["Anão Forjado em Rocha","Anão Couro-de-Pedra","Anão Mente Forte","Anão da Forja","Anão da Tumba"],"needs_review":false}'::jsonb),
  ('ancestry.elf', 'Elfo', 'Elf', 'Elfo', 'Ancestralidade ágil e longeva, adaptável a muitos estudos e ambientes.', 'An agile, long-lived ancestry adaptable to many studies and environments.', 'Una ascendencia ágil y longeva, adaptable a muchos estudios y ambientes.', 6, 'Médio', 30, ARRAY['Destreza', 'Inteligência', 'Livre']::text[], 'Constituição', ARRAY['Comum', 'Élfico']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 46, '{"senses":["Visão na Penumbra"],"heritagesList":["Elfo da Floresta Antiga","Elfo do Ártico","Elfo da Caverna","Elfo Vidente","Elfo Nômade dos Sussurros"],"needs_review":false}'::jsonb),
  ('ancestry.gnome', 'Gnomo', 'Gnome', 'Gnomo', 'Ancestralidade pequena ligada à curiosidade, magia e experiências intensas.', 'A Small ancestry tied to curiosity, magic, and vivid experiences.', 'Una ascendencia Pequeña vinculada a la curiosidad, la magia y experiencias intensas.', 8, 'Pequeno', 25, ARRAY['Constituição', 'Carisma', 'Livre']::text[], 'Força', ARRAY['Comum', 'Gnomo', 'Silvestre']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 50, '{"senses":["Visão na Penumbra"],"heritagesList":["Gnomo Camaleão","Gnomo Feérico","Gnomo Sensitivo","Gnomo do Umbral","Gnomo Poço de Vigor"],"needs_review":false}'::jsonb),
  ('ancestry.goblin', 'Goblin', 'Goblin', 'Goblin', 'Ancestralidade pequena, inventiva e enérgica, com grande variedade cultural.', 'A Small, inventive, energetic ancestry with broad cultural variety.', 'Una ascendencia Pequeña, inventiva y enérgica, con gran variedad cultural.', 6, 'Pequeno', 25, ARRAY['Destreza', 'Carisma', 'Livre']::text[], 'Sabedoria', ARRAY['Comum', 'Goblin']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 54, '{"senses":["Visão no Escuro"],"heritagesList":["Goblin Cabeça-Dura","Goblin Carbonizado (Resistência a Fogo)","Goblin Irritadiço","Goblin Dente-de-Navalha","Goblin Macaco"],"needs_review":false}'::jsonb),
  ('ancestry.halfling', 'Halfling', 'Halfling', 'Mediano', 'Ancestralidade pequena, observadora e corajosa, conhecida por sua sorte.', 'A Small, observant, courageous ancestry known for good fortune.', 'Una ascendencia Pequeña, observadora y valiente, conocida por su fortuna.', 6, 'Pequeno', 25, ARRAY['Destreza', 'Sabedoria', 'Livre']::text[], 'Força', ARRAY['Comum', 'Halfling']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 58, '{"senses":["Visão na Penumbra"],"heritagesList":["Halfling Pés-Leves","Halfling Destemido","Halfling Esguio","Halfling Nômade da Colina","Halfling Abençoado pela Sorte"],"needs_review":false}'::jsonb),
  ('ancestry.leshy', 'Leshy', 'Leshy', 'Leshy', 'Espírito da natureza em um corpo vegetal, com formas e heranças variadas.', 'A nature spirit inhabiting a plant body, with varied forms and heritages.', 'Un espíritu de la naturaleza en un cuerpo vegetal, con formas y herencias variadas.', 8, 'Pequeno', 25, ARRAY['Constituição', 'Sabedoria', 'Livre']::text[], 'Inteligência', ARRAY['Comum', 'Silvestre']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 66, '{"senses":["Visão na Penumbra"],"heritagesList":["Leshy Folhoso","Leshy Frutífero","Leshy Espinhoso","Leshy Fúngico","Leshy da Flor de Lótus"],"needs_review":false}'::jsonb),
  ('ancestry.orc', 'Orc', 'Orc', 'Orco', 'Ancestralidade vigorosa e tenaz, moldada por sobrevivência e comunidade.', 'A vigorous, tenacious ancestry shaped by survival and community.', 'Una ascendencia vigorosa y tenaz, moldeada por la supervivencia y la comunidad.', 10, 'Médio', 25, ARRAY['Força', 'Livre']::text[], NULL, ARRAY['Comum', 'Orc']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 70, '{"senses":["Visão no Escuro"],"heritagesList":["Orc dos Ermos","Orc Couro-de-Batalha","Orc da Chuva Profunda","Orc Cicatrizado","Orc Presa-de-Ferro"],"needs_review":false}'::jsonb),
  ('ancestry.catfolk', 'Amurrun', 'Catfolk', 'Pueblo felino', 'Ancestralidade felina, curiosa e ágil, com forte vínculo comunitário.', 'A curious, agile feline ancestry with strong community bonds.', 'Una ascendencia felina, curiosa y ágil, con fuertes lazos comunitarios.', 8, 'Médio', 25, ARRAY['Destreza', 'Carisma', 'Livre']::text[], 'Sabedoria', ARRAY['Comum', 'Amurrun']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 8, '{"senses":["Visão na Penumbra"],"heritagesList":["Povo-Gato Caçador","Povo-Gato Garra-Flexível","Povo-Gato Nove-Vidas","Povo-Gato da Selva"],"needs_review":false}'::jsonb),
  ('ancestry.ratfolk', 'Ysoki', 'Ratfolk', 'Pueblo rata', 'Ancestralidade ratoide pequena, diligente, adaptável e voltada à vida comunitária.', 'A Small, diligent, adaptable rat-like ancestry centered on community life.', 'Una ascendencia Pequeña de aspecto rata, diligente, adaptable y comunitaria.', 6, 'Pequeno', 25, ARRAY['Destreza', 'Inteligência', 'Livre']::text[], 'Força', ARRAY['Comum', 'Ysoki']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 36, '{"senses":["Visão na Penumbra"],"heritagesList":["Povo-Rato das Profundezas","Povo-Rato da Tempestade","Povo-Rato Bochecha Longa","Povo-Rato dos Túneis"],"needs_review":false}'::jsonb),
  ('ancestry.kobold', 'Kobold', 'Kobold', 'Kobold', 'Ancestralidade reptiliana pequena, engenhosa e influenciada por fontes poderosas de magia.', 'A Small, ingenious reptilian ancestry influenced by powerful sources of magic.', 'Una ascendencia reptiliana Pequeña e ingeniosa, influida por poderosas fuentes de magia.', 6, 'Pequeno', 25, ARRAY['Destreza', 'Carisma', 'Livre']::text[], 'Constituição', ARRAY['Comum', 'Dracônico']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 24, '{"senses":["Visão no Escuro"],"heritagesList":["Kobold Escama-Dracônica","Kobold Venenoso","Kobold Cavernoso","Kobold Tece-Feitiço"],"needs_review":false}'::jsonb),
  ('ancestry.lizardfolk', 'Iruxi', 'Lizardfolk', 'Pueblo lagarto', 'Ancestralidade reptiliana de tradições antigas e grande capacidade de sobrevivência.', 'A reptilian ancestry with ancient traditions and strong survival instincts.', 'Una ascendencia reptiliana de tradiciones antiguas y gran capacidad de supervivencia.', 8, 'Médio', 25, ARRAY['Força', 'Sabedoria', 'Livre']::text[], 'Inteligência', ARRAY['Comum', 'Iruxi']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 16, '{"senses":[],"heritagesList":["Iruxi dos Penhascos","Iruxi Aquático","Iruxi Couro-de-Placas","Iruxi Caçador Noturno"],"needs_review":false}'::jsonb),
  ('ancestry.kitsune', 'Kitsune', 'Kitsune', 'Kitsune', 'Humanoides raposinos metamorfos ligados ao mundo espiritual.', 'Foxlike shapeshifters tied to the spirit world.', 'Cambiaformas con rasgos de zorro vinculados al mundo espiritual.', 8, 'Médio', 25, ARRAY['Carisma', 'Livre']::text[], NULL, ARRAY['Comum', 'Silvestre']::text[], ARRAY[]::text[], 'common', 'legacy', 'Ancestry Guide (pré-Remaster)', 120, '{"senses":[],"heritagesList":["Kitsune Celestial","Kitsune da Terra","Kitsune Espiritual","Kitsune Fogo-Fátuo"],"needs_review":false}'::jsonb),
  ('ancestry.tengu', 'Tengu', 'Tengu', 'Tengu', 'Ancestralidade aviária sociável, inventiva e conhecida por sua afinidade com lâminas.', 'A sociable, inventive avian ancestry known for an affinity with blades.', 'Una ascendencia aviar sociable e inventiva, conocida por su afinidad con las hojas.', 6, 'Médio', 25, ARRAY['Destreza', 'Livre']::text[], NULL, ARRAY['Comum', 'Tengu']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 28, '{"senses":[],"heritagesList":["Tengu Bico-de-Navalha","Tengu Olho-da-Tempestade","Tengu Asa-Céu","Tengu da Montanha"],"needs_review":false}'::jsonb),
  ('ancestry.tripkee', 'Tripkee', 'Tripkee', 'Tripkee', 'Ancestralidade anfíbia pequena, paciente e naturalmente apta a escalar.', 'A Small, patient amphibian ancestry naturally suited to climbing.', 'Una ascendencia anfibia Pequeña, paciente y naturalmente hábil para trepar.', 6, 'Pequeno', 25, ARRAY['Destreza', 'Sabedoria', 'Livre']::text[], 'Força', ARRAY['Comum', 'Tripkee']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 32, '{"senses":[],"heritagesList":["Tripkee Peletóxica","Tripkee Ribeirinho","Tripkee Línguaveloz","Tripkee Dedoaderente","Tripkee Peledura","Tripkee Flutuante"],"needs_review":false}'::jsonb),
  ('ancestry.azarketi', 'Azarketi', 'Azarketi', 'Azarketi', 'Povo anfíbio adaptado à vida terrestre e aquática.', 'An amphibious people adapted to life on land and underwater.', 'Un pueblo anfibio adaptado a la vida terrestre y submarina.', 8, 'Médio', 25, ARRAY['Constituição', 'Carisma', 'Livre']::text[], 'Sabedoria', ARRAY['Comum', 'Aquano']::text[], ARRAY[]::text[], 'common', 'legacy', 'Ancestry Guide (pré-Remaster)', 16, '{"senses":[],"heritagesList":["Azarketi dos Mares Profundos","Azarketi Fluvial","Azarketi Escamado","Azarketi Névoa"],"needs_review":false}'::jsonb),
  ('ancestry.automaton', 'Autômato', 'Automaton', 'Autómata', 'Constructo consciente criado no antigo Império Jistka e sustentado por uma alma viva.', 'A sentient construct created in the ancient Jistka Imperium and sustained by a living soul.', 'Un constructo consciente creado en el antiguo Imperio Jistka y sostenido por un alma viva.', 10, 'Médio', 25, ARRAY['Força', 'Livre']::text[], NULL, ARRAY['Comum', 'Utopiano']::text[], ARRAY[]::text[], 'common', 'legacy', 'Pólvora e Engrenagens (pré-Remaster)', 36, '{"senses":[],"heritagesList":["Autômato Blindado","Autômato de Caça Veloz","Autômato do Núcleo Brilhante","Autômato Guerreiro"],"needs_review":false}'::jsonb),
  ('ancestry.android', 'Androide', 'Android', 'Androide', 'Seres biotecnológicos com corpos artificiais e mentes conscientes.', 'Biotechnological people with artificial bodies and conscious minds.', 'Seres biotecnológicos con cuerpos artificiales y mentes conscientes.', 8, 'Médio', 25, ARRAY['Destreza', 'Inteligência', 'Livre']::text[], 'Carisma', ARRAY['Comum', 'Androide']::text[], ARRAY[]::text[], 'common', 'legacy', 'Ancestry Guide (pré-Remaster)', 22, '{"senses":["Visão na Penumbra"],"heritagesList":["Andróide Artesão","Andróide Caçador","Andróide Sombra","Andróide Guerreiro"],"needs_review":false}'::jsonb),
  ('ancestry.kholo', 'Kholo', 'Kholo', 'Kholo', 'Ancestralidade de aspecto hienídeo, pragmática e dedicada à comunidade e aos ancestrais.', 'A hyena-like, pragmatic ancestry devoted to community and ancestors.', 'Una ascendencia de aspecto hiena, pragmática y dedicada a la comunidad y los ancestros.', 8, 'Médio', 25, ARRAY['Força', 'Inteligência', 'Livre']::text[], 'Sabedoria', ARRAY['Comum', 'Gnoll']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 20, '{"senses":[],"heritagesList":["Kholo Mandíbula de Ferro","Kholo dos Desfiladeiros","Kholo Fantasma"],"needs_review":false}'::jsonb),
  ('ancestry.fetchling', 'Kayal', 'Fetchling', 'Hijo de las sombras', 'Descendentes de habitantes do Plano das Sombras, adaptados à penumbra.', 'Descendants of the Shadow Plane, adapted to dimness and darkness.', 'Descendientes del Plano de las Sombras, adaptados a la penumbra.', 8, 'Médio', 25, ARRAY['Destreza', 'Livre']::text[], NULL, ARRAY['Comum', 'Sombrio']::text[], ARRAY[]::text[], 'common', 'legacy', 'Ancestry Guide (pré-Remaster)', 30, '{"senses":["Visão no Escuro"],"heritagesList":["Kayal das Sombras Profundas","Kayal Furtivo","Kayal Sem Rosto"],"needs_review":false}'::jsonb),
  ('ancestry.hobgoblin', 'Hobgoblin', 'Hobgoblin', 'Hobgoblin', 'Ancestralidade disciplinada e resistente, marcada por organização e pragmatismo.', 'A disciplined, resilient ancestry shaped by organization and pragmatism.', 'Una ascendencia disciplinada y resistente, marcada por la organización y el pragmatismo.', 8, 'Médio', 25, ARRAY['Constituição', 'Inteligência', 'Livre']::text[], 'Sabedoria', ARRAY['Comum', 'Goblin']::text[], ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 12, '{"senses":["Visão no Escuro"],"heritagesList":["Hobgoblin Couro de Ferro","Hobgoblin Fumegante","Hobgoblin Vanguarda"],"needs_review":false}'::jsonb),
  ('ancestry.skeleton', 'Esqueleto', 'Skeleton', 'Esqueleto', 'Ancestralidade rara morta-viva com 6 PV, visão no escuro e necessidade de coletar ossos.', 'A rare undead ancestry with 6 HP, darkvision, and a need to collect bones.', 'Una ascendencia rara no muerta con 6 PG, visión en la oscuridad y necesidad de recoger huesos.', 6, 'Médio', 25, ARRAY['Destreza', 'Carisma', 'Livre']::text[], 'Inteligência', ARRAY['Comum', 'Necril']::text[], ARRAY['Morto-vivo']::text[], 'rare', 'legacy', 'Livro dos Mortos (pré-Remaster)', 48, '{"senses":["Visão no Escuro"],"heritagesList":["Esqueleto-Bucha","Esqueleto Compacto","Esqueleto Monstruoso","Esqueleto Robusto"],"needs_review":false}'::jsonb),
  ('ancestry.centaur', 'Centauro', 'Centaur', 'Centauro', 'Nômade Grande, veloz e robusto, ligado à proteção da comunidade e da natureza.', 'A Large, swift, and sturdy nomad devoted to community and the natural world.', 'Un nómada Grande, veloz y robusto dedicado a su comunidad y al mundo natural.', 8, 'Grande', 30, ARRAY['Força', 'Sabedoria', 'Livre']::text[], 'Carisma', ARRAY['Comum', 'Feérico']::text[], ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 28, '{"senses":["Visão na Penumbra"],"heritagesList":["Centauro Orador Nascente","Centauro Vento-Veloz","Centauro Casco de Ferro","Centauro Malhado","Centauro Passo de Pônei","Centauro Coração Robusto"],"needs_review":false}'::jsonb),
  ('ancestry.minotaur', 'Minotauro', 'Minotaur', 'Minotauro', 'Construtor e explorador Grande, resistente e dotado de chifres naturais.', 'A Large, resilient builder and explorer armed with natural horns.', 'Un constructor y explorador Grande y resistente, armado con cuernos naturales.', 10, 'Grande', 25, ARRAY['Força', 'Constituição', 'Livre']::text[], 'Carisma', ARRAY['Comum', 'Jotun']::text[], ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 40, '{"senses":["Visão no Escuro"],"heritagesList":["Minotauro Touro Fantasma","Minotauro da Caverna Glacial","Minotauro Chifre Pequeno","Minotauro Errante","Minotauro Alma de Laje","Minotauro Espreitador"],"needs_review":false}'::jsonb),
  ('ancestry.awakened_animal', 'Animal Desperto', 'Awakened Animal', 'Animal despierto', 'Animal raro que recebeu consciência plena; tamanho, PV e deslocamentos dependem de sua forma escolhida.', 'A rare animal granted full sapience; its size, HP, and Speeds depend on its chosen form.', 'Un animal raro que recibió plena conciencia; su tamaño, PG y velocidades dependen de la forma elegida.', 8, 'Medium', 25, ARRAY['Constituição', 'Sabedoria', 'Livre']::text[], 'Inteligência', ARRAY['Comum']::text[], ARRAY[]::text[], 'rare', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 22, '{"senses":["Visão na Penumbra"],"heritagesList":["Animal Escalador","Animal Voador","Animal Corredor","Animal Nadador"],"needs_review":false}'::jsonb),
  ('ancestry.merfolk.legacy_alias.trit_o_sereia_merfolk', 'Povo-Sereia', 'Merfolk', 'Sirénido', 'Povo anfíbio dos oceanos que combina graça aquática, canto e magia das águas.', 'An amphibious ocean people combining aquatic grace, song, and water magic.', 'Un pueblo oceánico anfibio que combina gracia acuática, canto y magia del agua.', 8, 'Médio', 5, ARRAY['Destreza', 'Carisma', 'Livre']::text[], 'Constituição', ARRAY['Comum', 'Talássico']::text[], ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 34, '{"senses":["Visão na Penumbra"],"heritagesList":["Povo-Sereia Abissal","Povo-Sereia Carcharodonte","Povo-Sereia Pelágico","Povo-Sereia de Recife","Povo-Sereia Agulhão"],"needs_review":false}'::jsonb),
  ('ancestry.athamaru.legacy_alias.athamaru_povo_peixe', 'Athamaru', 'Athamaru', 'Athamaru', 'Povo anfíbio comunitário, adaptado aos recifes e à vida subaquática.', 'A communal amphibious people adapted to reefs and undersea life.', 'Un pueblo anfibio comunitario adaptado a los arrecifes y la vida submarina.', 8, 'Médio', 20, ARRAY['Força', 'Sabedoria', 'Livre']::text[], 'Inteligência', ARRAY['Comum', 'Talássico']::text[], ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 16, '{"senses":["Visão na Penumbra"],"heritagesList":["Athamaru Coralino","Athamaru Esperançoso","Athamaru Caleidoscópico","Athamaru Espinhoso"],"needs_review":false}'::jsonb),
  ('ancestry.surki.legacy_alias.surki_povo_inseto', 'Surki', 'Surki', 'Surki', 'Povo insetoide raro que absorve magia ambiental e desenvolve adaptações metamórficas.', 'A rare insectile people who absorb ambient magic and develop metamorphic adaptations.', 'Un pueblo insectoide raro que absorbe magia ambiental y desarrolla adaptaciones metamórficas.', 8, 'Médio', 25, ARRAY['Constituição', 'Livre']::text[], NULL, ARRAY['Comum', 'Surki']::text[], ARRAY[]::text[], 'rare', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 46, '{"senses":["Visão no Escuro"],"heritagesList":["Surki Rompedor","Surki Élitro","Surki Carapaça Dura","Surki Lanterna"],"needs_review":false}'::jsonb),
