  ('item.compendium.signal_whistle', 'Apito de Sinal', 'Signal Whistle', 'Silbato de señales', 'Apito agudo audível a mais de 800 metros em terreno aberto.', 'A shrill whistle audible from more than 800 meters in open terrain.', 'Un silbato agudo audible a más de 800 metros en terreno abierto.', 'Gear', 0, 0.08, '-', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.soap', 'Sabão', 'Soap', 'Jabón', 'Barra de sabão perfumado para higiene pessoal em viagens.', 'A scented bar of soap for personal hygiene while traveling.', 'Una pastilla de jabón perfumado para la higiene personal durante los viajes.', 'Gear', 0, 0.02, '-', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.spyglass', 'Luneta', 'Spyglass', 'Catalejo', 'Luneta de latão e lentes polidas que aproxima objetos distantes em até 10 vezes.', 'A brass spyglass with polished lenses that magnifies distant objects up to ten times.', 'Un catalejo de latón con lentes pulidas que aumenta hasta diez veces los objetos distantes.', 'Gear', 4, 80, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.ten_foot_pole', 'Vara de 3 Metros', 'Ten-foot Pole', 'Pértiga de 3 metros', 'Vara de madeira rígida de 3 metros para testar pisos e desarmar armadilhas.', 'A rigid 3-meter wooden pole for testing floors and triggering traps from a distance.', 'Una vara rígida de madera de 3 metros para probar suelos y activar trampas a distancia.', 'Gear', 0, 0.01, '1', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.thieves_tools', 'Ferramentas de Ladrão', 'Thieves'' Tools', 'Herramientas de ladrón', 'Gazuas, arames e alavancas para arrombar fechaduras e desativar armadilhas.', 'Lockpicks, wires, and levers for picking locks and disabling traps.', 'Ganzúas, alambres y palancas para forzar cerraduras y desactivar trampas.', 'Gear', 0, 3, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb)
