  ('item.compendium.torch', 'Tocha', 'Torch', 'Antorcha', 'Tocha de madeira com estopa embebida em piche que queima por 1 hora (luz em 6m).', 'A wooden torch with pitch-soaked cloth that burns for 1 hour (6-meter light).', 'Una antorcha de madera con tela empapada en brea que arde durante 1 hora (luz de 6 metros).', 'Gear', 0, 0.01, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.waterskin', 'Odre', 'Waterskin', 'Odre', 'Odre de couro com capacidade para 1 litro de água fresca.', 'A leather waterskin holding 1 liter of fresh water.', 'Un odre de cuero con capacidad para 1 litro de agua fresca.', 'Gear', 0, 0.05, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.writing_set', 'Conjunto de Escrita', 'Writing Set', 'Juego de escritura', 'Pena, tinta nanquim, pergaminhos e cera para selagem de cartas.', 'A quill, ink, parchment, and sealing wax for writing and sealing letters.', 'Una pluma, tinta, pergamino y cera de sellado para escribir y cerrar cartas.', 'Gear', 0, 1, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.elixir_of_life_minor', 'Elixir da Vida (Menor)', 'Elixir of Life (Minor)', 'Elixir de vida (menor)', 'Ao beber, recupera 1d6 Pontos de Vida e concede +1 de bônus de item em testes de Fortitude contra venenos e doenças por 1 hora.', 'When consumed, you regain 1d6 Hit Points and gain a +1 item bonus to Fortitude saves against poisons and diseases for 1 hour.', 'Al beberlo, recuperas 1d6 Puntos de Golpe y obtienes un bonificador de objeto +1 a las salvaciones de Fortaleza contra venenos y enfermedades durante 1 hora.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Elixir', 'Cura']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.elixir_of_life_lesser', 'Elixir da Vida (Inferior)', 'Elixir of Life (Lesser)', 'Elixir de vida (menor potente)', 'Ao beber, recupera 3d6+6 Pontos de Vida e concede +1 de bônus de item em testes contra venenos e doenças.', 'When consumed, you regain 3d6+6 Hit Points and gain a +1 item bonus to saves against poisons and diseases.', 'Al beberlo, recuperas 3d6+6 Puntos de Golpe y obtienes un bonificador de objeto +1 a las salvaciones contra venenos y enfermedades.', 'Consumables', 5, 12, 'L', NULL, ARRAY['Alquímico', 'Elixir', 'Cura']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.healing_potion_minor', 'Poção de Cura (Menor)', 'Healing Potion (Minor)', 'Poción de curación (menor)', 'Poção mágica efervescente de coloração rubi que cura instantaneamente 1d8 Pontos de Vida.', 'An effervescent ruby-colored magic potion that immediately restores 1d8 Hit Points.', 'Una poción mágica efervescente de color rubí que restaura inmediatamente 1d8 Puntos de Golpe.', 'Consumables', 1, 4, 'L', NULL, ARRAY['Mágico', 'Poção', 'Cura']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.healing_potion_lesser', 'Poção de Cura (Inferior)', 'Healing Potion (Lesser)', 'Poción de curación (menor potente)', 'Poção mágica potente que cura instantaneamente 2d8+5 Pontos de Vida.', 'A potent magic potion that immediately restores 2d8+5 Hit Points.', 'Una potente poción mágica que restaura inmediatamente 2d8+5 Puntos de Golpe.', 'Consumables', 3, 12, 'L', NULL, ARRAY['Mágico', 'Poção', 'Cura']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.alchemist_s_fire_lesser', 'Fogo Alquímico (Inferior)', 'Alchemist''s Fire (Lesser)', 'Fuego alquímico (menor)', 'Frasco volátil que causa 1d8 de dano de fogo no impacto, 1 de dano de fogo contínuo e 1 de dano de fogo em respingo.', 'A volatile flask dealing 1d8 fire damage on impact, 1 persistent fire damage, and 1 splash fire damage.', 'Un frasco volátil que causa 1d8 de daño de fuego al impactar, 1 de daño de fuego persistente y 1 de daño de fuego por salpicadura.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Bomba', 'Fogo']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.acid_flask_lesser', 'Frasco de Ácido (Inferior)', 'Acid Flask (Lesser)', 'Frasco de ácido (menor)', 'Causa 1 de dano de ácido, 1d6 de dano de ácido contínuo e 1 de dano de ácido em respingo.', 'It deals 1 acid damage, 1d6 persistent acid damage, and 1 splash acid damage.', 'Inflige 1 de daño de ácido, 1d6 de daño de ácido persistente y 1 de daño de ácido por salpicadura.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Bomba', 'Ácido']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.frost_vial_lesser', 'Vial de Frio (Inferior)', 'Frost Vial (Lesser)', 'Vial de escarcha (menor)', 'Causa 1d6 de dano de frio, 1 de respingo e aplica penalidade de -3m no deslocamento da vítima.', 'It deals 1d6 cold damage, 1 splash damage, and gives the victim a –3-meter penalty to Speed.', 'Inflige 1d6 de daño de frío, 1 de salpicadura y aplica una penalización de –3 metros a la Velocidad de la víctima.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Bomba', 'Frio']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.bottled_lightning_lesser', 'Relâmpago Engarrafado (Inferior)', 'Bottled Lightning (Lesser)', 'Rayo embotellado (menor)', 'Causa 1d6 de dano elétrico, 1 de respingo e deixa o alvo Desprevenido até o início do próximo turno.', 'It deals 1d6 electricity damage, 1 splash damage, and leaves the target off-guard until the start of its next turn.', 'Inflige 1d6 de daño eléctrico, 1 de salpicadura y deja al objetivo desprevenido hasta el inicio de su próximo turno.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Bomba', 'Eletricidade']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.tanglefoot_bag_lesser', 'Bolsa de Resina (Inferior)', 'Tanglefoot Bag (Lesser)', 'Bolsa de enredadera (menor)', 'Bolsa de resina expansiva que gruda nas pernas do alvo, reduzindo a velocidade em 3m ou imobilizando no acerto crítico.', 'An expanding resin bag that sticks to the target''s legs, reducing Speed by 3 meters or immobilizing it on a critical hit.', 'Una bolsa de resina expansiva que se adhiere a las piernas del objetivo, reduce su Velocidad en 3 metros o lo inmoviliza con un golpe crítico.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.antidote_lesser', 'Antídoto (Inferior)', 'Antidote (Lesser)', 'Antídoto (menor)', 'Concede +2 de bônus de item em testes de salvaguarda contra venenos por 6 horas.', 'It grants a +2 item bonus to saves against poisons for 6 hours.', 'Concede un bonificador de objeto +2 a las salvaciones contra venenos durante 6 horas.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Elixir']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.antiplague_lesser', 'Antipeste (Inferior)', 'Antiplague (Lesser)', 'Antiplaga (menor)', 'Concede +2 de bônus de item em testes de salvaguarda contra doenças por 24 horas.', 'It grants a +2 item bonus to saves against diseases for 24 hours.', 'Concede un bonificador de objeto +2 a las salvaciones contra enfermedades durante 24 horas.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Elixir']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.smokestick_lesser', 'Bastão de Fumaça (Inferior)', 'Smokestick (Lesser)', 'Bastón de humo (menor)', 'Cria uma nuvem de fumaça espessa de 1,5m que concede Ocultação a criaturas dentro dela por 1 minuto.', 'It creates a 1.5-meter cloud of thick smoke that gives creatures inside it concealment for 1 minute.', 'Crea una nube de humo denso de 1,5 metros que proporciona ocultamiento a las criaturas dentro durante 1 minuto.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.sunrod', 'Bastão Solar', 'Sunrod', 'Bastón solar', 'Bastão alquímico que brilha com luz solar viva de 6m por 6 horas após ser quebrado.', 'An alchemical rod that shines with sunlight in a 6-meter radius for 6 hours after being broken.', 'Una vara alquímica que brilla con luz solar en un radio de 6 metros durante 6 horas al romperse.', 'Consumables', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Luz']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.tindertwig', 'Graveto de Ignição', 'Tindertwig', 'Ramita yesquera', 'Fósforo alquímico de ignição instantânea que acende tochas em 1 única ação.', 'An alchemical match that ignites instantly and lights torches with a single action.', 'Una cerilla alquímica de ignición instantánea que enciende antorchas con una sola acción.', 'Consumables', 1, 0.2, '-', NULL, ARRAY['Alquímico']::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.1_weapon_potency_rune', 'Runa de Potência de Arma +1', '+1 Weapon Potency Rune', 'Runa de potencia de arma +1', 'Runa fundamental mágica que concede +1 de bônus de item em jogadas de ataque com a arma gravada.', 'A fundamental magic rune granting a +1 item bonus to attack rolls with the etched weapon.', 'Una runa mágica fundamental que concede un bonificador de objeto +1 a las tiradas de ataque con el arma grabada.', 'Runes', 2, 35, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.2_weapon_potency_rune', 'Runa de Potência de Arma +2', '+2 Weapon Potency Rune', 'Runa de potencia de arma +2', 'Runa fundamental mágica que concede +2 de bônus de item em jogadas de ataque com a arma gravada.', 'A fundamental magic rune granting a +2 item bonus to attack rolls with the etched weapon.', 'Una runa mágica fundamental que concede un bonificador de objeto +2 a las tiradas de ataque con el arma grabada.', 'Runes', 10, 935, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.3_weapon_potency_rune', 'Runa de Potência de Arma +3', '+3 Weapon Potency Rune', 'Runa de potencia de arma +3', 'Runa fundamental mágica que concede +3 de bônus de item em jogadas de ataque com a arma gravada.', 'A fundamental magic rune granting a +3 item bonus to attack rolls with the etched weapon.', 'Una runa mágica fundamental que concede un bonificador de objeto +3 a las tiradas de ataque con el arma grabada.', 'Runes', 16, 8935, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.striking_rune', 'Runa Impactante', 'Striking Rune', 'Runa impactante', 'Runa fundamental que adiciona 1 dado extra de dano da arma ao acertar (2 dados no total).', 'A fundamental rune that adds 1 extra weapon damage die on a hit (2 dice total).', 'Una runa fundamental que añade 1 dado de daño adicional del arma al impactar (2 dados en total).', 'Runes', 4, 65, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.greater_striking_rune', 'Runa Impactante Maior', 'Greater Striking Rune', 'Runa impactante mayor', 'Runa fundamental que adiciona 2 dados extras de dano da arma ao acertar (3 dados no total).', 'A fundamental rune that adds 2 extra weapon damage dice on a hit (3 dice total).', 'Una runa fundamental que añade 2 dados de daño adicionales del arma al impactar (3 dados en total).', 'Runes', 12, 1065, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.major_striking_rune', 'Runa Impactante Superior', 'Major Striking Rune', 'Runa impactante mayor superior', 'Runa fundamental lendária que adiciona 3 dados extras de dano da arma ao acertar (4 dados no total).', 'A legendary fundamental rune that adds 3 extra weapon damage dice on a hit (4 dice total).', 'Una runa fundamental legendaria que añade 3 dados de daño adicionales del arma al impactar (4 dados en total).', 'Runes', 19, 31065, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.1_armor_potency_rune', 'Runa de Potência de Armadura +1', '+1 Armor Potency Rune', 'Runa de potencia de armadura +1', 'Runa fundamental que concede +1 de bônus de item na CA da armadura ou traje de explorador.', 'A fundamental rune granting a +1 item bonus to the armor or explorer''s clothing AC.', 'Una runa fundamental que concede un bonificador de objeto +1 a la CA de la armadura o la ropa de explorador.', 'Runes', 5, 160, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 242, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.resilient_rune', 'Runa Resiliente', 'Resilient Rune', 'Runa resistente', 'Runa fundamental de armadura que concede +1 de bônus de item em todas as salvaguardas (Fortitude, Reflexos, Vontade).', 'A fundamental armor rune granting a +1 item bonus to all saves (Fortitude, Reflex, and Will).', 'Una runa fundamental de armadura que concede un bonificador de objeto +1 a todas las salvaciones (Fortaleza, Reflejos y Voluntad).', 'Runes', 8, 340, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 243, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.flaming_property_rune', 'Runa de Propriedade Flamejante', 'Flaming Property Rune', 'Runa de propiedad flamígera', 'Adiciona 1d6 de dano de fogo adicional e 1d10 de dano contínuo de fogo no acerto crítico.', 'It adds 1d6 additional fire damage and 1d10 persistent fire damage on a critical hit.', 'Añade 1d6 de daño de fuego adicional y 1d10 de daño de fuego persistente con un golpe crítico.', 'Runes', 8, 500, '-', NULL, ARRAY['Mágico', 'Fogo', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 244, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.frost_property_rune', 'Runa de Propriedade Gélida', 'Frost Property Rune', 'Runa de propiedad gélida', 'Adiciona 1d6 de dano de frio adicional e deixa o alvo Lento 1 no acerto crítico.', 'It adds 1d6 additional cold damage and makes the target Slowed 1 on a critical hit.', 'Añade 1d6 de daño de frío adicional y deja al objetivo ralentizado 1 con un golpe crítico.', 'Runes', 8, 500, '-', NULL, ARRAY['Mágico', 'Frio', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 244, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.shocking_property_rune', 'Runa de Propriedade Chocante', 'Shocking Property Rune', 'Runa de propiedad impactante', 'Adiciona 1d6 de dano elétrico adicional e propaga 1d4 de dano elétrico em criaturas adjacentes no crítico.', 'It adds 1d6 additional electricity damage and deals 1d4 electricity damage to adjacent creatures on a critical hit.', 'Añade 1d6 de daño eléctrico adicional y causa 1d4 de daño eléctrico a criaturas adyacentes con un golpe crítico.', 'Runes', 8, 500, '-', NULL, ARRAY['Mágico', 'Eletricidade', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 245, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.returning_property_rune', 'Runa de Propriedade Retornante', 'Returning Property Rune', 'Runa de propiedad retornante', 'Quando você arremessa a arma gravada, ela retorna imediatamente à sua mão logo após o ataque.', 'When you throw the etched weapon, it immediately returns to your hand after the attack.', 'Cuando lanzas el arma grabada, vuelve inmediatamente a tu mano tras el ataque.', 'Runes', 3, 55, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 245, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.ghost_touch_property_rune', 'Runa de Propriedade Toque Fantasma', 'Ghost Touch Property Rune', 'Runa de propiedad toque fantasmal', 'A arma atinge criaturas incorpóreas com eficácia total, ignorando resistências a dano físico.', 'The weapon affects incorporeal creatures with full effect, ignoring physical damage resistances.', 'El arma afecta plenamente a las criaturas incorpóreas e ignora sus resistencias al daño físico.', 'Runes', 4, 75, '-', NULL, ARRAY['Mágico', 'Runa']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 244, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.spacious_pouch_bag_of_holding', 'Bolsa Espaçosa (Bolsa de Carga)', 'Spacious Pouch (Bag of Holding)', 'Bolsa espaciosa (bolsa de contención)', 'Bolsa mágica dimensional capaz de carregar até 25 de Carga enquanto pesa apenas 1 de Carga.', 'A magical dimensional bag that can carry up to 25 Bulk while weighing only 1 Bulk.', 'Una bolsa mágica dimensional capaz de transportar hasta 25 de Carga mientras pesa solo 1 de Carga.', 'Gear', 4, 75, '1', NULL, ARRAY['Extradimensional', 'Mágico']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 254, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.boots_of_elvenkind', 'Botas Élficas', 'Boots of Elvenkind', 'Botas élficas', 'Botas leves que concedem +1 de bônus de item em testes de Furtividade e permitem ignorar terreno difícil suave.', 'Light boots granting a +1 item bonus to Stealth checks and letting you ignore uneven ground.', 'Botas ligeras que conceden un bonificador de objeto +1 a las pruebas de Sigilo y permiten ignorar terreno difícil menor.', 'Gear', 7, 340, 'L', NULL, ARRAY['Investimento', 'Mágico']::text[], 'uncommon', 'remaster', 'Guia do Mestre (GM Core)', 257, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.cloak_of_elvenkind', 'Manto Élfico', 'Cloak of Elvenkind', 'Capa élfica', 'Manto cambiante que concede +1 de bônus em Furtividade e permite conjurar Invisibilidade 1 vez por dia.', 'A shifting cloak granting a +1 bonus to Stealth and allowing you to cast invisibility once per day.', 'Una capa cambiante que concede un bonificador +1 a Sigilo y permite lanzar invisibilidad una vez al día.', 'Gear', 7, 360, 'L', NULL, ARRAY['Investimento', 'Ilusão', 'Mágico']::text[], 'uncommon', 'remaster', 'Guia do Mestre (GM Core)', 259, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.goggles_of_night', 'Óculos da Noite', 'Goggles of Night', 'Gafas de la noche', 'Óculos de lentes de quartzo escurecido que concedem Visão no Escuro contínua ao usuário investido.', 'Goggles with dark quartz lenses that grant the invested wearer continuous darkvision.', 'Gafas con lentes de cuarzo oscuro que conceden visión en la oscuridad permanente a quien las inviste.', 'Gear', 5, 150, 'L', NULL, ARRAY['Investimento', 'Mágico']::text[], 'uncommon', 'remaster', 'Guia do Mestre (GM Core)', 262, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.wand_of_heal_1st_rank', 'Varinha de Curar (1º Ranque)', 'Wand of Heal (1st-Rank)', 'Varita de curar (rango 1)', 'Varinha entalhada em freixo que permite conjurar a magia Curar de 1º ranque uma vez ao dia (ou arriscar sobrecarga).', 'An ash wand that lets you cast the 1st-rank heal spell once per day (or risk overcharging it).', 'Una varita de fresno que permite lanzar curar de rango 1 una vez al día (o arriesgarse a sobrecargarla).', 'Gear', 3, 60, 'L', NULL, ARRAY['Mágico', 'Varinha']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 290, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.compendium.staff_of_fire', 'Cajado do Fogo', 'Staff of Fire', 'Bastón de fuego', 'Cajado mágico forjado em madeira carbonizada com cargas diárias para conjurar Raio de Fogo e Mãos Flamejantes.', 'A magic staff of charred wood with daily charges for casting Produce Flame and Burning Hands.', 'Un bastón mágico de madera carbonizada con cargas diarias para lanzar producir llama y manos ardientes.', 'Gear', 4, 90, '1', NULL, ARRAY['Investimento', 'Mágico', 'Cajado']::text[], 'common', 'remaster', 'Guia do Mestre (GM Core)', 292, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.animal_nip', 'Mordida Animal', 'Animal Nip', 'Cebo animal', 'Pó aromático que atrai animais: criaturas em uma emanação de 9 metros fazem Vontade ou ficam fascinadas por 1 rodada; falha crítica também as deixa caídas.', 'A fragrant powder attracts animals: creatures in a 30-foot emanation attempt Will or become fascinated for 1 round; a critical failure also knocks them prone.', 'Un polvo fragante atrae animales: las criaturas en una emanación de 9 metros hacen Voluntad o quedan fascinadas 1 asalto; un fallo crítico también las derriba.', 'magical', 4, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 200, '{"usage":null,"effects":[],"mechanics":{"usage":"segurado em 1 mão","bulk":"negligível","activate":"1 ação, Manuseio","area":"emanação de 9 metros","save":"Vontade","duration":"1 rodada","effect":"Fascinado","criticalFailure":"também fica caído","immunity":"1 hora; Fascinação termina após ato hostil","dc":"18 menor; 24 moderada; 30 maior"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.blooming_lotus_seed_pod', 'Vagem de Sementes de Lótus Florescente', 'Blooming Lotus Seed Pod', 'Vaina de semillas de loto floreciente', 'Vagem que cria cinco plataformas de lótus sobre líquidos por 1 minuto ou uma flor que concede descanso prolongado e imunidade a efeitos que afetam apenas criaturas dormindo.', 'A pod creates five lotus pads on liquid for 1 minute or a flower that grants long-term rest and immunity to effects affecting only sleeping creatures.', 'Una vaina crea cinco plataformas de loto sobre líquidos durante 1 minuto o una flor que concede descanso prolongado e inmunidad a efectos que solo afectan a criaturas dormidas.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 200, '{"usage":null,"effects":[],"mechanics":{"usage":"segurado em 1 mão","bulk":"L","floatingPads":"1 ação; cinco plataformas em líquido não danoso a até 12 metros; cada uma raio 3 metros e dura 1 minuto","capacity":"1 criatura Grande, 2 Médias ou 4 Pequenas por plataforma","bloomingFlower":"10 minutos; plantada no solo","rest":"por 8 horas; dormir 6 horas a até 9 metros conta como um dia/noite de descanso","immunity":"pesadelo e efeitos mágicos que afetam apenas criaturas dormindo"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.broadleaf_shield', 'Escudo de Folha Larga', 'Broadleaf Shield', 'Escudo de hoja ancha', 'Escudo de folha que regenera ao ficar 10 minutos sob luz solar e concede resistência sazonal, dobrada quando erguido.', 'A leaf shield regrows after 10 minutes in sunlight and grants seasonal resistance, doubled while Raised.', 'Un escudo de hoja se regenera tras 10 minutos al sol y concede resistencia estacional, duplicada mientras está Alzado.', 'magical', 6, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 200, '{"usage":null,"effects":[],"mechanics":{"usage":"segurado em 1 mão","bulk":"L","seasons":"rosa: void; verde: fogo; laranja: veneno; marrom: frio","resistance":"3 (6 quando Erguido) no tipo da estação","changeSeason":"1 ação, Concentração; 1/dia; escolhe cor por 5 minutos","base":"Dureza 4, 16 PV, BT 8","variants":"maior: Dureza 6/24 PV/BT 12/resistência 4; maior superior: 8/32/16/5; verdadeiro: 10/40/20/6"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.captivating_rosebud', 'Botão de Rosa Cativante', 'Captivating Rosebud', 'Capullo de rosa cautivador', 'Broto que cresce em roseira perfumada: criaturas que passam a até 4,5 metros fazem Vontade e podem sofrer penalidade de Percepção ou ficar fascinadas; também pode criar uma roseira-escada.', 'A bud grows into a fragrant rosebush: creatures passing within 15 feet attempt Will and can take a Perception penalty or become fascinated; it can also grow a climbable rosebush.', 'Un capullo crece en un rosal fragante: las criaturas que pasan a 4,5 metros hacen Voluntad y pueden sufrir penalización a Percepción o quedar fascinadas; también puede crear un rosal escalable.', 'magical', 3, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 200, '{"usage":null,"effects":[],"mechanics":{"throw":"1 ação; espaço adjacente; dura 1 hora","scent":"criatura a até 4,5 metros faz Vontade CD 18","criticalSuccess":"sem efeito","success":"–1 de estado em Percepção por 10 minutos","failure":"–2 de estado em Percepção por 10 minutos","criticalFailure":"–2 de estado e Fascinado","roseVines":"10 minutos; cresce até 9 metros junto a estrutura; você/aliados Escalam facilmente; outros fazem Vontade CD 17 para notar"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.carver_cutter', 'Machado Entalhador', 'Carver-Cutter', 'Hacha talladora', 'Machado de batalha +2 striking com cinzel removível que funciona como main-gauche, concede bônus de Manufatura em madeira e causa dano extra a criaturas de planta ou madeira.', 'A +2 striking battle axe has a removable chisel that functions as a main-gauche, grants a Crafting bonus for woodworking, and deals extra damage to plant or wooden creatures.', 'Un hacha de batalla +2 striking tiene un cincel extraíble que funciona como main-gauche, concede bonificación de Artesanía para madera y causa daño adicional a criaturas vegetales o de madera.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 201, '{"usage":null,"effects":[],"mechanics":{"weapon":"+2 striking machado de batalha","usage":"segurado em 1 mão","bulk":"1","chisel":"1 ação; +2 item em Manufatura para madeira; funciona como main-gauche; runas copiadas enquanto juntos","chopDown":"2 ações, 1/hora; Golpe contra planta ou criatura de madeira, +2d6 precisão e Desajeitado 1 por 1 minuto","variants":"maior: +2 greater striking/+3d6; maior superior: +2 keen greater striking/+3d6; verdadeiro: +3 keen greater striking/+3d6 e +3 Manufatura/+4d6"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.glowing_lantern_fruit', 'Fruto Lanterna Brilhante', 'Glowing Lantern Fruit', 'Fruta linterna brillante', 'Fruto que ilumina como lanterna por 8 horas e pode ser plantado para emitir luz e calor de fogueira, protegendo do frio próximo.', 'A fruit sheds lantern-like light for 8 hours or can be planted to emit bonfire light and heat, protecting nearby creatures from cold.', 'Una fruta emite luz como linterna durante 8 horas o puede plantarse para emitir luz y calor de hoguera, protegiendo del frío a criaturas cercanas.', 'magical', 1, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 201, '{"usage":null,"effects":[],"mechanics":{"usage":"segurado em 1 mão","bulk":"L","lanternLight":"1 ação; luz plena 18 metros e luz fraca mais 18 metros por 8 horas; folhas direcionam a luz","fireFruit":"10 minutos; plantado de cabeça para baixo; luz e calor de fogueira por 8 horas","coldProtection":"imunidade aos efeitos de frio moderado e severo a até 4,5 metros"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.kizidhars_shield', 'Escudo de Kizidhar', 'Kizidhar''s Shield', 'Escudo de Kizidhar', 'Escudo de duskwood que se repara por 1 minuto e pode proteger um acampamento com espinhos por 8 horas e curar seus ocupantes.', 'A duskwood shield repairs itself for 1 minute and can protect a campsite with thorns for 8 hours while healing its occupants.', 'Un escudo de madera crepuscular se repara durante 1 minuto y puede proteger un campamento con espinas durante 8 horas mientras cura a sus ocupantes.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 202, '{"usage":null,"effects":[],"mechanics":{"shield":"escudo de duskwood padrão; segurado em 1 mão; Volume L","repair":"1 ação, 1/dia; por 1 minuto cura 3 PV no início do seu turno","secureSite":"10 minutos, 1/dia; acampamento de até 9 metros de lado; efeito como muralha de espinhos por 8 horas","healing":"criaturas no acampamento recebem Cura de 4º círculo"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.purifying_spoon', 'Colher Purificadora', 'Purifying Spoon', 'Cuchara purificadora', 'Colher de madeira que purifica comida ou bebida uma vez por dia ao ser mexida, com variantes para diferentes volumes.', 'A wooden spoon purifies food or drink once per day when stirred, with variants for different volumes.', 'Una cuchara de madera purifica comida o bebida una vez al día al removerla, con variantes para distintos volúmenes.', 'magical', 1, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 202, '{"usage":null,"effects":[],"mechanics":{"activate":"2 ações, 1/dia; lança cleanse cuisine","teaspoon":"Nível 1, 10 po, até 1 galão","tablespoon":"Nível 1, 20 po, até 8 galões","ladle":"Nível 2, 32 po, até 16 galões"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.rooting', 'Enraizamento', 'Rooting', 'Enraizamiento', 'Runa para arma corpo a corpo: em um acerto crítico, raízes imobilizam o alvo por 1 rodada e o deixam desajeitado enquanto permanecer imobilizado.', 'A melee weapon rune grows roots on a critical hit, immobilizing the target for 1 round and making it clumsy while immobilized.', 'Una runa para arma cuerpo a cuerpo hace crecer raíces con un crítico, inmovilizando al objetivo 1 asalto y dejándolo torpe mientras esté inmovilizado.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 202, '{"usage":null,"effects":[],"mechanics":{"usage":"gravada em arma corpo a corpo","trigger":"acerto crítico","effect":"Imobilizado por 1 rodada e Desajeitado 1 enquanto imobilizado","escape":"CD 23; maior CD 28; maior superior CD 34; verdadeiro CD 41"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.sandalwood_fan', 'Leque de Sândalo', 'Sandalwood Fan', 'Abanico de sándalo', 'Leque que reduz o erro de teleporte planar, fala com plantas e cria folhas que dão cobertura a aliados e luz reveladora a inimigos.', 'A fan reduces planar teleportation error, speaks with plants, and creates leaves that grant allies cover and reveal enemies.', 'Un abanico reduce el error del teletransporte planar, habla con plantas y crea hojas que dan cobertura a aliados y revelan enemigos.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 202, '{"usage":null,"effects":[],"mechanics":{"usage":"segurado em 1 mão","bulk":"L","planarKey":"erro de interplanar reduzido para 1d6×25 milhas; 1d4×25 milhas quando destino é a paisagem do leque","plantSpeech":"1 minuto, 1/dia; speak with plants e translate para Fey e Muan","cloudOfLeaves":"2 ações, 1/dia; aliados e indiferentes a até 9 metros recebem cobertura menor por 1 rodada; inimigos recebem revealing light por 1 minuto"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.splintering_spear', 'Lança Estilhaçante', 'Splintering Spear', 'Lanza astilladora', 'Lança +2 de duskwood greater striking que causa 1d6 de sangramento persistente e pode explodir em estilhaços, regenerando-se ao fim do turno.', 'A +2 duskwood greater striking spear deals 1d6 persistent bleed and can shatter into splinters, regrowing at the end of the turn.', 'Una lanza +2 de madera crepuscular greater striking causa 1d6 de sangrado persistente y puede romperse en astillas, regenerándose al final del turno.', 'magical', 13, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 202, '{"usage":null,"effects":[],"mechanics":{"weapon":"+2 duskwood greater striking lança","usage":"segurada em 1 mão","bulk":"L","hit":"1d6 sangramento persistente","shatter":"2 ações, 1/dia; cone de 9 metros ou emanação de 3 metros; 12d6 perfurante, Reflexos básico CD 30; falha também aplica o sangramento da arma","regrowth":"retorna à forma completa no fim do turno","variants":"maior: +3 high-grade duskwood greater striking, 16d6/CD 37; maior superior: +3 high-grade duskwood superior striking, 18d6/CD 43"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.tailors_boll', 'Bola do Alfaiate', 'Tailor''s Boll', 'Bola del sastre', 'Bola de algodão mágico que tece uma roupa não mágica de explorador ou fina sob medida até o início do próximo turno, sem mudar o tipo da roupa existente.', 'A magical cotton boll weaves nonmagical explorer''s or fine clothing to order by the start of your next turn and cannot change an existing clothing type.', 'Una bola de algodón mágica teje ropa no mágica de explorador o fina a medida para el inicio de tu próximo turno y no puede cambiar el tipo de ropa existente.', 'magical', 3, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 203, '{"usage":null,"effects":[],"mechanics":{"activate":"2 ações, Concentração/Manuseio","result":"roupa pronta no início do próximo turno em local conveniente","types":"roupa de explorador ou fina","reweave":"se segurar roupa na outra mão, retecela no estilo pedido","limitation":"não muda o tipo do item; não transforma roupa fina em explorador ou inverno"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.tales_in_timber', 'Contos na Madeira', 'Tales in Timber', 'Historias en madera', 'Armadura de peito de madeira resiliente com histórias entalhadas: concede bônus de Natureza e pode assumir disfarce de estátua, além de afetar você com resiliência de carvalho e falar com plantas.', 'A resilient wooden breastplate grants a Nature bonus and can disguise you as a wooden statue, also affecting you with oaken resilience and speak with plants.', 'Una coraza de madera resistente concede bonificación de Naturaleza y puede disfrazarte como estatua de madera, además de afectarte con resistencia de roble y hablar con plantas.', 'magical', 10, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 202, '{"usage":null,"effects":[],"mechanics":{"armor":"+1 resilient breastplate de madeira; uso armadura vestida; Volume 2","nature":"+2 item em Natureza para Recordar Conhecimento; ritual collective memories permite usar Natureza","statueDisguise":"2 ações, 1/dia; por 1 hora, disfarce ilusório de 3º círculo com criatura retratada; concede oaken resilience e speak with plants","still":"+2 item em Dissimulação para parecer estátua quando imóvel","variants":"maior: +2 resilient e resiliência de carvalho 4º; maior superior: +2 greater resilient, +3 Natureza e resiliência 6º"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.therapeutic_snap_peas', 'Ervilhas Estalantes Terapêuticas', 'Therapeutic Snap Peas', 'Guisantes terapéuticos', 'Vagem que cura até cinco criaturas e melhora salvamentos contra venenos ou doenças; plantada, cresce em uma trepadeira com alimento e cura adicional.', 'A pod heals up to five creatures and improves saves against poisons or diseases; planted, it grows into a beanstalk with food and additional healing.', 'Una vaina cura hasta cinco criaturas y mejora salvaciones contra venenos o enfermedades; plantada, crece en una enredadera con comida y curación adicional.', 'magical', 8, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 202, '{"usage":null,"effects":[],"mechanics":{"healingPod":"2 ações, até 5 criaturas escolhidas a até 9 metros; recuperam 4d8+10 PV e recebem +2 item em salvamentos contra venenos/doenças por 1 minuto","beanstalk":"10 minutos; cresce 3 metros e dura 8 horas","food":"vagens alimentam até 8 criaturas vivas Grandes ou menores por um dia","extraHealing":"quem comer recupera 30 PV e pode tentar novo salvamento contra um veneno ou doença"},"needs_review":false}'::jsonb),
  ('item.rage_elements.wood.thorn_triad', 'Tríade de Espinhos', 'Thorn Triad', 'Tríada de espinas', 'Spellheart que conjura Tronco e, após uma magia de planta, concede resistência contra contundente/perfurante ou dano de sangramento adicional às armas.', 'A wooden spellheart casts Timber and, after a plant spell, grants bludgeoning/piercing resistance on armor or additional bleed damage to weapon Strikes.', 'Un spellheart de madera lanza Tronco y, tras un conjuro de planta, concede resistencia a contundente/perforante en armadura o daño de sangrado adicional a Golpes con armas.', 'magical', 4, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 203, '{"usage":null,"effects":[],"mechanics":{"usage":"afixado a armadura não metálica ou arma","spellDC":"18; maior 24; maior superior 29","armor":"após magia de planta: resistência 2 a contundente/perfurante e fraqueza 3 a fogo até fim do próximo turno; resistência dobra para magia não truque","weapon":"após magia de planta: Golpes causam +1d4 sangramento persistente até fim do próximo turno; variantes +1d6/+1d8","activate":"Conjurar uma Magia: Tronco; maior 1/dia muralha de espinhos; maior superior 1/dia muralha de espinhos de 4º e tempestade de pétalas"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.aboutface_figurehead', 'Figura de Proa Meia-Volta', 'Aboutface Figurehead', 'Mascarón de proa media vuelta', 'Figura de proa que suprime a condição sluggish do navio e pode fazê-lo virar 180 graus em seu próprio eixo uma vez por dia.', 'A figurehead suppresses a ship''s sluggish vehicle ability and can turn it 180 degrees in place once per day.', 'Un mascarón suprime la capacidad sluggish del vehículo y puede girarlo 180 grados en su sitio una vez al día.', 'magical', 10, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 176, '{"usage":null,"effects":[],"mechanics":{"usage":"anexada à proa de um navio","suppresses":"habilidade sluggish do veículo","activate":"1 ação; 1/dia; concentrar e movimento","effect":"o navio faz uma curva de 180 graus no próprio eixo e segue na nova direção no próximo turno"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.anglerfish_lantern', 'Lanterna Peixe-Pescador', 'Anglerfish Lantern', 'Linterna de rape', 'Lanterna que brilha automaticamente submersa e pode fascinar criaturas; a variante submersível transforma-se em batiesfera.', 'A lantern shines automatically underwater and can fascinate creatures; its submersible variant transforms into a bathysphere.', 'Una linterna brilla automáticamente bajo el agua y puede fascinar criaturas; su variante sumergible se transforma en batiesfera.', 'magical', 5, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 176, '{"usage":null,"effects":[],"mechanics":{"usage":"segurada em 1 mão; Volume 1","activate":"2 ações; concentração e manuseio; 1/hora","save":"Vontade CD 19; criaturas aquáticas ou com traço Água sofrem –2 circunstancial","effect":"Fascinado por 1 rodada; falha crítica por 1 minuto; imunidade por 24 horas","variants":"submersível nível 8, CD 24; 1 minuto, 1/dia, transforma-se em batiesfera por 1 hora em água com pelo menos 4,5 metros"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.brine_dragon_scale', 'Escama de Dragão de Salmoura', 'Brine Dragon Scale', 'Escama de dragón de salmuera', 'Talismã afixado a uma arma que causa 2d8 de ácido a uma criatura que usa uma ação de concentração e pode interromper a ação em falha crítica.', 'A weapon talisman deals 2d8 acid damage to a creature using a concentrate action and can disrupt it on a critical failure.', 'Un talismán de arma causa 2d8 de ácido a una criatura que usa una acción de concentración y puede interrumpirla con un fallo crítico.', 'magical', 8, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 176, '{"usage":null,"effects":[],"mechanics":{"usage":"afixada a uma arma corpo a corpo","trigger":"criatura ao alcance usa ação com traço Concentração","prerequisite":"especialista na arma","activate":"reação; Concentração","damage":"2d8 ácido","save":"Reflexos básico CD 24","criticalFailure":"ação de concentração desencadeadora é interrompida"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.conch_of_otherworldly_seas', 'Concha dos Mares de Outro Mundo', 'Conch of Otherworldly Seas', 'Caracola de mares sobrenaturales', 'Instrumento musical virtuoso que concede bônus de Performance, facilita viagens ao Plano da Água e permite falar Thalassic ou conjurar clairaudience subaquática.', 'A virtuoso instrument grants a Performance bonus, improves travel to the Plane of Water, and enables Thalassic speech or underwater clairaudience.', 'Un instrumento virtuoso concede bonificación a Interpretación, mejora los viajes al Plano del Agua y permite hablar Thalassic o usar clairaudience bajo el agua.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 176, '{"usage":null,"effects":[],"mechanics":{"usage":"segurada em 2 mãos; Volume L","performance":"+2 item em Performance","planarKey":"viagem ao Plano da Água chega a 1d6×25 milhas do destino, em vez de 1d10×25; 1d6×25 quando sintonizada às águas do destino","voiceOfOceans":"1 ação; entende e fala Thalassic enquanto segurada ao ouvido","soundsOfTheDeep":"10 minutos; clairaudience de 5º círculo; alcance 1 milha e clareza perfeita em local subaquático"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.faydhaans_dallah', 'Dallah de Faydhaan', 'Faydhaan''s Dallah', 'Dallah de Faydhaan', 'Jarra que prepara seis xícaras de café; quem bebe respira debaixo d''água e fica protegido de temperaturas subaquáticas, e a ativação diária pode transformar a bebida em uma poção.', 'A dallah brews six cups of coffee; drinkers breathe underwater and withstand underwater temperatures, and a daily activation can transmute the batch into a potion.', 'Una dallah prepara seis tazas de café; quienes beben respiran bajo el agua y resisten temperaturas subacuáticas, y una activación diaria puede transformar el lote en una poción.', 'magical', 14, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 177, '{"usage":null,"effects":[],"mechanics":{"usage":"segurada em 1 mão; Volume 1","brew":"3 ações; mói grãos, enche-se de água e prepara seis xícaras","coffee":"respiração aquática e proteção contra temperaturas subaquáticas moderadas ou severas por 8 horas","hospitality":"2 ações; 1/dia; transforma o café do lote em uma poção comum de 6º nível ou inferior para todos que beberam","examples":"poção moderada de cura, poção menor de resistência ou poção de natação"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.kraken_figurehead', 'Figura de Proa Kraken', 'Kraken Figurehead', 'Mascarón de proa kraken', 'Figura de proa que cria tentáculos espectrais para atrapalhar natação e prender ou puxar embarcações inimigas.', 'A figurehead creates spectral tentacles that hinder swimming and tether or pull enemy vessels.', 'Un mascarón crea tentáculos espectrales que dificultan nadar y atan o atraen embarcaciones enemigas.', 'magical', 10, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 177, '{"usage":null,"effects":[],"mechanics":{"usage":"anexada à proa de um navio","lashOut":"2 ações; aura por 10 minutos; –2 circunstancial em Atletismo para Nadar","grabThem":"1 ação; ataque; teste de pilotagem contra CA do navio","success":"prende os navios; –2 em pilotagem inimiga; +2 para Abordar","pull":"puxa até metade da Velocidade de natação do navio, ou a Velocidade inteira em sucesso crítico","variants":"wracking nível 14; CD para libertar 31; causa 7d10 contundente ao casco em falha/sucesso apropriado"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.lionfish_spear', 'Lança Peixe-Leão', 'Lionfish Spear', 'Lanza pez león', 'Lança +2 striking underwater wounding que concede bônus para Nadar e injeta veneno de peixe-leão uma vez por dia; possui variantes maiores.', 'A +2 striking underwater wounding spear grants a bonus to Swim and injects lionfish poison once per day, with greater variants.', 'Una lanza +2 striking underwater wounding concede una bonificación para Nadar e inyecta veneno de pez león una vez al día, con variantes mayores.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 177, '{"usage":null,"effects":[],"mechanics":{"weapon":"+2 striking underwater wounding lança","usage":"segurada em 1 mão; Volume 1","swim":"+2 item em Atletismo para Nadar","activate":"reação; 1/dia; após Acerto com a lança","save":"Fortitude CD 28","poison":"duração máxima 6 rodadas; estágio 1: 3d6 veneno e enjoado 1; estágio 2: 5d6 veneno e enjoado 2; estágio 3: paralisado por 2d4 horas","variants":"greater: +2 greater striking, +1d6 veneno, 1/hora, CD 31"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.octopus_potion', 'Poção de Polvo', 'Octopus Potion', 'Poción de pulpo', 'Poção de metamorfose que cria braços de polvo, tentando agarrar um inimigo aleatório e impondo cegueira, silêncio, dificuldade de Manuseio ou dano contundente.', 'A morph potion creates octopus arms that Grapple a random enemy and can blind, silence, hamper manipulate actions, or deal bludgeoning damage.', 'Una poción de metamorfosis crea brazos de pulpo que Agarran a un enemigo aleatorio y pueden cegar, silenciar, dificultar acciones de Manipular o causar daño contundente.', 'magical', 6, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 178, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; Manuseio","range":"15 pés","duration":"1 minuto","initial":"braços compartilham penalidade de múltiplos ataques e tentam Agarrar","effects":"1: cego; 2: não pode falar; 3: CD da prova simples para Manusear enquanto agarrado vira 7; 4: dano contundente igual ao nível ao agarrar e no fim de cada turno","variants":"menor Atletismo +12/CD de Escapar 20; moderada +17/25; maior +22/30"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.sharkskin_robe', 'Robe de Pele de Tubarão', 'Sharkskin Robe', 'Túnica de piel de tiburón', 'Robe investido que concede deslocamento de natação igual ao terrestre, bônus de Atletismo e faz ataques funcionarem como armas subaquáticas por 1 minuto.', 'An invested robe grants a swim Speed equal to land Speed, an Athletics bonus, and underwater weapon benefits for 1 minute.', 'Una túnica investida concede una Velocidad de nado igual a la terrestre, bonificación a Atletismo y beneficios de arma subacuática durante 1 minuto.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 178, '{"usage":null,"effects":[],"mechanics":{"usage":"vestida; Volume 1","swim":"Velocidade de natação igual à Velocidade terrestre","athletics":"+2 item em Atletismo","activate":"2 ações; 1/hora; por 1 minuto, cada Golpe recebe benefício da runa de arma subaquática"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.shell_of_easy_breathing', 'Concha da Respiração Fácil', 'Shell of Easy Breathing', 'Concha de respiración fácil', 'Concha que se enche de água salgada e permite a uma criatura respirar debaixo d''água por 1 hora; a variante maior dura 8 horas.', 'A shell fills with saltwater and lets a creature breathe underwater for 1 hour; the greater version lasts 8 hours.', 'Una concha se llena de agua salada y permite respirar bajo el agua durante 1 hora; la versión mayor dura 8 horas.', 'magical', 5, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 178, '{"usage":null,"effects":[],"mechanics":{"fill":"1 ação; 1 minuto; coloca em superfície e adiciona gotas de água","breathe":"atividade de 3 ações; submerge a cabeça na concha; respira debaixo d''água por 1 hora","immunity":"imune a esta concha até as próximas preparações diárias","variant":"greater nível 9; duração 8 horas"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.sticky_algae_bomb', 'Bomba de Algas Pegajosas', 'Sticky Algae Bomb', 'Bomba de algas pegajosas', 'Bomba alquímica de água que não sofre penalidades subaquáticas, causa dano de veneno e deixa o alvo com um rastro bioluminescente rastreável.', 'A water bomb ignores underwater penalties, deals poison damage, and leaves its target with a trackable bioluminescent trail.', 'Una bomba de agua ignora penalizaciones subacuáticas, causa daño de veneno y deja un rastro bioluminiscente rastreable.', 'magical', 1, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 178, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; Golpe","underwater":"ignora penalidades e restrições normais de ataques na água ou debaixo d''água","trail":"rastro visível por 1 hora apenas na água; CD 19 para Rastrear","variants":"menor 1d8 veneno + 1 splash; moderada 2d8 + 2 splash e +1 ataque; maior 3d8 + 3 splash e +2; major 4d8 + 4 splash e +3"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.underwater', 'Subaquática', 'Underwater', 'Subacuática', 'Runa de arma que remove as penalidades e restrições normais de ataques realizados na água ou debaixo d''água e mantém dano de fogo funcionando.', 'A weapon rune removes normal underwater attack penalties and restrictions and lets fire damage function underwater.', 'Una runa de arma elimina las penalizaciones y restricciones normales de ataques bajo el agua y permite que el daño de fuego funcione.', 'magical', 3, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 178, '{"usage":null,"effects":[],"mechanics":{"usage":"gravada em uma arma","effect":"a arma funciona na água como em terra; ataques não sofrem penalidades ou restrições normais da água; fogo da arma funciona debaixo d''água"},"needs_review":false}'::jsonb),
  ('item.rage_elements.water.veiled_figurehead', 'Figura de Proa Velada', 'Veiled Figurehead', 'Mascarón de proa velado', 'Figura de proa que disfarça a aparência do navio por 6 horas; a variante maior também disfarça a tripulação e pode alterar sua ancestralidade aparente.', 'A figurehead disguises a ship for 6 hours; the greater version also disguises its crew and can alter their apparent ancestry.', 'Un mascarón disfraza un barco durante 6 horas; la versión mayor también disfraza a su tripulación y puede cambiar su ascendencia aparente.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 179, '{"usage":null,"effects":[],"mechanics":{"usage":"anexada à proa de um navio","activate":"1 minuto; 1/dia; Concentração, Ilusão e Visual","effect":"altera cor, marcas, velas, material e danos superficiais sem mudar tamanho ou forma geral","duration":"6 horas ou até Dissipar","disbelief":"Percepção CD 25 ao embarcar ou Buscar; maior CD 33 e duração 24 horas","greater":"variante maior lança veil na tripulação, altera roupas e pode fazer todos parecerem da mesma ancestralidade escolhida"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.aerial_cloak', 'Manto Aéreo', 'Aerial Cloak', 'Capa aérea', 'Manto leve que concede bônus para Saltar, Equilibrar e Manobrar em Voo e reduz uma queda uma vez por dia.', 'A light cloak grants bonuses to Leap, Balance, and Maneuver in Flight and shortens a fall once per day.', 'Una capa ligera concede bonificaciones para Saltar, Equilibrio y Maniobrar en Vuelo y acorta una caída una vez al día.', 'magical', 3, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 74, '{"usage":null,"effects":[],"mechanics":{"bonuses":"+1 em Atletismo para Saltar e +1 em Acrobacia para Equilibrar ou Manobrar em Voo","activate":"reação; 1/dia; quando cai","effect":"queda 9 metros mais curta e plana até espaço a até 6 metros do ponto de aterrissagem"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.atmospheric_staff', 'Bastão Atmosférico', 'Atmospheric Staff', 'Bastón atmosférico', 'Cajado mágico que protege contra movimento forçado e conjura magias de ar, gravidade e voo conforme a variante.', 'A magical staff protects against forced movement and casts air, gravity, and flight spells by variant.', 'Un bastón mágico protege contra movimiento forzado y lanza conjuros de aire, gravedad y vuelo según la variante.', 'magical', 4, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 74, '{"usage":null,"effects":[],"mechanics":{"saves":"+1 item em salvamentos contra movimento forçado","activate":"Conjurar uma Magia; gasta cargas","variants":"menor: gale blast, air bubble, gravitational pull; padrão: gentle breeze, gravity well, tempest cloak; maior: fly, variable gravity, elemental form (ar), telekinetic haul; major: zero gravity, elemental form (ar), vacuum"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.blight_breath', 'Sopro da Praga', 'Blight Breath', 'Aliento de plaga', 'Respiração engarrafada que concede resistência a veneno enquanto prende a respiração e libera 10d6 de veneno em cone.', 'Bottled breath grants poison resistance while held and releases 10d6 poison damage in a cone.', 'Un aliento embotellado concede resistencia al veneno mientras se contiene y libera 10d6 de veneno en un cono.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 74, '{"usage":null,"effects":[],"mechanics":{"resistance":"10 a veneno enquanto prende a respiração","exhale":"1 ação; cone de 4,5 metros; 10d6 veneno; Reflexos básico CD 29"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.extra_lung', 'Pulmão Extra', 'Extra Lung', 'Pulmón adicional', 'Pulmão extra com cinco rodadas de ar, recarregável, que captura uma aflição inalada e permite novo salvamento.', 'An extra lung holds five rounds of air, can be refilled, and captures an inhaled affliction for a new save.', 'Un pulmón extra contiene cinco asaltos de aire, puede rellenarse y captura una aflicción inhalada para otra salvación.', 'magical', 8, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 74, '{"usage":null,"effects":[],"mechanics":{"capacity":"5 rodadas; recarrega aberto por 10 minutos em ar adequado","switching":"troca sem ação; falar não consome seu ar","activate":"reação ao inalar veneno ou aflição","effect":"tosse o veneno para o pulmão e tenta novo salvamento; limpa-se ao amanhecer"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.fan_of_soothing_winds', 'Leque dos Ventos Calmantes', 'Fan of Soothing Winds', 'Abanico de vientos calmantes', 'Leque com seis contas que conjura curar em cone uma vez por dia por conta; a variante maior usa círculos mais altos.', 'A six-bead fan casts heal in a cone once per day per bead; the greater version uses higher ranks.', 'Un abanico de seis cuentas lanza curar en un cono una vez al día por cuenta; la variante mayor usa rangos superiores.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 74, '{"usage":null,"effects":[],"mechanics":{"activate":"2 ações; 1/dia por conta","effect":"curar de 3 ações em cone de 9 metros; CD 28 contra mortos-vivos; contas 4º, 3º e 2º círculo; traço Ar","variant":"greater: CD 34; círculos 6º, 5º e 4º"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.floating_tent', 'Tenda Flutuante', 'Floating Tent', 'Tienda flotante', 'Tenda flutuante ancorável para ambientes sem gravidade, com versões para uma ou quatro criaturas.', 'An anchorable floating tent for gravityless environments, with one-person and four-person versions.', 'Una tienda flotante anclable para entornos sin gravedad, con versiones para una o cuatro criaturas.', 'magical', 1, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 75, '{"usage":null,"effects":[],"mechanics":{"anchor":"impede que flutue","variants":"pup nível 1: uma criatura Média ou menor; four-person nível 2: quatro criaturas"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.frost_breath', 'Sopro Gélido', 'Frost Breath', 'Aliento de escarcha', 'Respiração engarrafada que concede resistência a frio e libera 4d6 de frio em cone, congelando o terreno.', 'Bottled breath grants cold resistance and releases 4d6 cold damage in a cone, icing the terrain.', 'Un aliento embotellado concede resistencia al frío y libera 4d6 de frío en un cono, congelando el terreno.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 75, '{"usage":null,"effects":[],"mechanics":{"resistance":"5 a frio enquanto prende a respiração","exhale":"1 ação; cone de 4,5 metros; 4d6 frio; Reflexos básico CD 20","terrain":"10 minutos; terreno difícil e irregular; Acrobacia CD 20"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.jaathooms_scarf', 'Cachecol de Jaathoom', 'Jaathoom''s Scarf', 'Bufanda de Jaathoom', 'Cachecol investido que melhora Performance de dança e Escapar, pode deixar você invisível e empurrar inimigos.', 'An invested scarf improves dance Performance and Escape, can turn you invisible, and push enemies.', 'Una bufanda investida mejora Interpretación de danza y Escapar, puede volverte invisible y empujar enemigos.', 'magical', 10, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 75, '{"usage":null,"effects":[],"mechanics":{"bonuses":"+2 item em Performance para dançar e Acrobacia para Escapar","vanish":"2 ações; 1/dia; invisibilidade de 4º círculo","rebuke":"1 ação; 1/hora; emanação de 3 metros; Fortitude CD 18; empurra 3 metros; falha crítica também derruba"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.nimbus_breath', 'Sopro de Nimbo', 'Nimbus Breath', 'Aliento de nimbo', 'Respiração engarrafada que concede resistência a eletricidade e voo enquanto prende a respiração, além de criar uma rajada de vento.', 'Bottled breath grants electricity resistance and fly while held, then creates a gust of wind.', 'Un aliento embotellado concede resistencia a electricidad y volar mientras se contiene, y crea una ráfaga de viento.', 'magical', 8, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 75, '{"usage":null,"effects":[],"mechanics":{"effect":"resistência 5 a eletricidade e fly enquanto prende a respiração","exhale":"1 ação; gust of wind CD 24","landing":"desce suavemente a 18 metros por rodada sem dano se estiver no ar"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.spiral_chimes', 'Sinos Espirais', 'Spiral Chimes', 'Campanas espirales', 'Sinos que melhoram viagens planares, preveem o clima e revelam criaturas invisíveis com som visível.', 'Chimes improve planar travel, forecast weather, and reveal invisible creatures with visible sound.', 'Unos carillones mejoran viajes planares, predicen el clima y revelan criaturas invisibles.', 'magical', 13, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 76, '{"usage":null,"effects":[],"mechanics":{"planarKey":"chega a 1d6×25 milhas do destino em vez de 1d10×25","forecast":"10 minutos; clima das próximas 24 horas","revealing":"1 ação; 1/dia; explosão de 9 metros a até 36; Reflexos CD 30; negação da invisibilidade e, em falha, ensurdece"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.spun_cloud', 'Nuvem Fiada', 'Spun Cloud', 'Nube hilada', 'Nuvem engarrafada que se expande em explosão e pode ocultar, proteger contra eletricidade, causar enjoo, amedrontar ou acelerar deslocamento.', 'Bottled cloud expands into a burst that can conceal, protect from electricity, sicken, frighten, or speed movement.', 'Una nube embotellada se expande en una explosión que puede ocultar, proteger, enfermar, asustar o acelerar.', 'magical', 2, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 76, '{"usage":null,"effects":[],"mechanics":{"area":"explosão de 6 metros a até 18 metros; dura 1 minuto","variants":"preta: ocultação; azul: resistência 5 eletricidade; verde: Fortitude CD 25 ou enjoado; vermelha: Vontade CD 24 ou assustado; branca: +3 metros em Velocidade"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.storm_breath', 'Sopro de Tempestade', 'Storm Breath', 'Aliento de tormenta', 'Respiração engarrafada que concede resistências a eletricidade e sônico e libera um raio de 4d12.', 'Bottled breath grants electricity and sonic resistance and releases a 4d12 lightning bolt.', 'Un aliento embotellado concede resistencias a electricidad y sónico y libera un rayo de 4d12.', 'magical', 9, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 76, '{"usage":null,"effects":[],"mechanics":{"resistance":"5 a eletricidade e sônico enquanto prende a respiração","exhale":"1 ação; linha de 9 metros; 4d12 eletricidade; Reflexos básico CD 25"},"needs_review":false}'::jsonb),
  ('item.rage_elements.air.wisp_chain', 'Cota de Fios de Ar', 'Wisp Chain', 'Cota de hilos de aire', 'Cota de malha resiliente de vento que ensurdece criaturas adjacentes e libera lâminas de ar em cone, recompondo-se no fim do turno.', 'A resilient wind chain shirt deafens adjacent creatures and releases slicing air in a cone, reforming at turn''s end.', 'Una camisa de malla de viento resistente ensordece criaturas adyacentes y libera aire cortante en un cono.', 'magical', 9, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 76, '{"usage":null,"effects":[],"mechanics":{"armor":"+1 resilient chain shirt","aura":"Fortitude CD 23; falha ensurdece até afastar-se","activate":"2 ações; cone de 18 metros; Fortitude básico CD 25","damage":"6d6 cortante; falha empurra 3 metros; falha crítica 6 metros","recovery":"perde o bônus de CA até o fim do turno","variants":"greater +2/CD 27 e 29; major +2 greater/CD 32 e 34; true +3 greater/CD 39 e 41"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.aeon_stone', 'Pedra Aeon', 'Aeon Stone', 'Piedra aeon', 'Pedra aeon com variantes de percepção, resistência mental ou salvamentos e poderes ressonantes diferentes.', 'An aeon stone with perception, mental resistance, or saving throw variants and distinct resonant powers.', 'Una piedra aeon con variantes de percepción, resistencia mental o salvaciones y poderes resonantes.', 'magical', 3, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 98, '{"usage":null,"effects":[],"mechanics":{"usage":"vestida; orbita a cabeça","variants":"cymophane: +2 Percepção e CDs contra Esconder-se, Furtividade e Roubar; see the unseen 1/dia; olivina: +2 salvamentos contra confuso, assustado e estupefato, reação suprime efeito por 1 minuto com –1 ataques; seixo: +1 Fortitude e CDs contra Agarrar/Engolir, grease primal 1/dia"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.drought_powder', 'Pó da Seca', 'Drought Powder', 'Polvo de sequía', 'Pó que mantém criatura e equipamentos secos, reduz um corpo d''água ou desacelera criaturas com traço Água.', 'Powder keeps a creature and gear dry, lowers a body of water, or slows creatures with the water trait.', 'El polvo mantiene seca a una criatura y su equipo, baja un cuerpo de agua o ralentiza criaturas con el rasgo Agua.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 98, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; Manuseio","dry":"você e itens carregados permanecem secos por 24 horas","water":"reduz água em área de 15 por 15 por 3 metros","creatures":"explosão de 3 metros a até 1,5 metro; criaturas Água sofrem slow; Fortitude CD 28"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.exuviae_powder', 'Pó de Exúvia', 'Exuviae Powder', 'Polvo de exuvias', 'Pó de exúvia que duplica o tempo prendendo a respiração e forma uma carapaça quando você seria petrificado.', 'Exuviae powder doubles breath-holding time and forms a shell when you would be petrified.', 'El polvo de exuvias duplica el tiempo conteniendo la respiración y forma una caparazón si fueras petrificado.', 'magical', 14, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 98, '{"usage":null,"effects":[],"mechanics":{"duration":"8 horas; duplica o tempo prendendo a respiração","shedChitin":"reação ao ser petrificado; efeito original termina; fica acelerado por 1 minuto, condenado 1 e restringido; Escapar CD 25"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.fossil_fragment', 'Fragmento Fóssil', 'Fossil Fragment', 'Fragmento fósil', 'Fragmento fóssil que se transforma em esqueleto de uma criatura, com variantes de mosquito, dinossauros, euriptérida ou árvore desperta.', 'A fossil fragment becomes a creature skeleton, with mosquito, dinosaur, eurypterid, or awakened tree variants.', 'Un fragmento fósil se convierte en el esqueleto de una criatura, con variantes de mosquito, dinosaurios, euriptérido o árbol despertado.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 98, '{"usage":null,"effects":[],"mechanics":{"activate":"2 ações; Concentração e Manuseio; coloca em solo e fala o nome","creature":"minion, construct e earth; obedece quando comandado; imunidades de construct","variants":"mosquito 1/dia por 10 minutos; brontossauro 4/mês, 24 horas fora de combate; deinonico 1/dia por 10 minutos; euriptérida 1/semana por 24 horas; madeira petrificada 1/dia por 1 minuto; tricerátopo/tyrannosaurus 1/dia por 10 minutos"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.jabalis_dice', 'Dados de Jabali', 'Jabali''s Dice', 'Dados de Jabali', 'Dados de pedra que concedem bônus em Saber de Jogos e invocam um shuyookh com um efeito aleatório de proteção ou magia.', 'Stone dice grant a Games Lore bonus and summon a shuyookh for a random protective or magical effect.', 'Dados de piedra conceden una bonificación a Saber de Juegos y convocan a un shuyookh para un efecto mágico aleatorio.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 99, '{"usage":null,"effects":[],"mechanics":{"lore":"+2 item em Saber de Jogos; também ao Obter Renda; um usuário por vez","activate":"2 ações; 1/dia; rola 2d6","results":"2–5 mountain resilience; 6–9 grasping earth; 10–11 wall of stone; 12 petrify CD 31 em inimigo próximo"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.limestone_shield', 'Escudo de Calcário', 'Limestone Shield', 'Escudo de piedra caliza', 'Escudo torre de calcário que se expande em muralha por 1 minuto e oferece cobertura contra efeitos de Ar, Fogo ou Água.', 'A limestone tower shield expands into a wall for 1 minute and grants cover against air, fire, or water effects.', 'Un escudo torre de piedra caliza se expande en un muro durante 1 minuto y da cobertura contra efectos de Aire, Fuego o Agua.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 99, '{"usage":null,"effects":[],"mechanics":{"shield":"Dureza 7, 28 PV, Volume 4","wall":"2 ações; 1/dia; muralha de até 18 metros por 3 metros; CA 10, Dureza 7, 28 PV por quadrado","block":"reação; 1/dia; contra efeito Ar, Fogo ou Água; cobertura padrão"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.robe_of_stone', 'Robe de Pedra', 'Robe of Stone', 'Túnica de piedra', 'Robe investido que concede sentido sísmico, Petran, nutrição por pedra e transformação em elemental da terra.', 'An invested robe grants tremorsense, Petran, nutrition from earth, and transformation into an earth elemental.', 'Una túnica investida concede sentido sísmico, Petran, nutrición de tierra y transformación en elemental de tierra.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 100, '{"usage":null,"effects":[],"mechanics":{"usage":"vestido; Volume L","senses":"tremorsense impreciso 3 metros","languages":"fala e lê Petran","nutrition":"pode comer terra, gemas e metal","activate":"2 ações; 1/dia; elemental form de terra; pode Escavar sem túneis; tremorsense aumenta para 9 metros"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.sairazul_blue', 'Azul de Sairazul', 'Sairazul Blue', 'Azul de Sairazul', 'Poção que concede resistência a veneno e void por 8 horas e cura 8d8 quando dano desses tipos reduz você a 0 PV.', 'A potion grants poison and void resistance for 8 hours and heals 8d8 when damage of either type reduces you to 0 HP.', 'Una poción concede resistencia a veneno y void durante 8 horas y cura 8d8 cuando ese daño te reduce a 0 PV.', 'magical', 10, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 100, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; Manuseio","duration":"8 horas","resistance":"5 a veneno e void","trigger":"cair a 0 PV por veneno ou void","healing":"8d8 PV; resistências terminam"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.sandcastle', 'Castelo de Areia', 'Sandcastle', 'Castillo de arena', 'Estrutura de areia que vira um castelo de até 36 metros por dimensão, com paredes resistentes e fraqueza a Água.', 'A sand structure becomes a castle up to 120 feet per dimension, with sturdy walls and weakness to water.', 'Una estructura de arena se convierte en un castillo de hasta 36 metros por dimensión, con muros resistentes y debilidad al agua.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 100, '{"usage":null,"effects":[],"mechanics":{"activate":"1 minuto; 1/dia; Concentração e Manuseio; pronuncia build em Petran","size":"até 36 metros por dimensão; paredes de 3 metros; andares de 3 metros","walls":"CA 10, Dureza 10, 40 PV por seção; imune a críticos e precisão; fraqueza 15 Água","return":"1 ação Interagir para devolver ao saco; água ou chuva forte desmorona"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.singing_stone', 'Pedra Cantante', 'Singing Stone', 'Piedra cantante', 'Pedra musical que melhora viagens planares, fala e escuta através de pedras e revela o interior de uma superfície rochosa.', 'A singing stone improves planar travel, speaks and listens through stone, and reveals the interior of rocky surfaces.', 'Una piedra cantante mejora viajes planares, habla y escucha a través de piedra y revela el interior de superficies rocosas.', 'magical', 13, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 100, '{"usage":null,"effects":[],"mechanics":{"planarKey":"chega a 1d6×25 milhas do destino em vez de 1d10×25","speech":"1 minuto; 1/dia; speak with stones; pode escolher uma pedra identificada no mesmo plano ou Plano da Terra","sight":"1 ação; 1/dia; imagem mental de 4,5 metros de profundidade por 1,5 metro de diâmetro; mostra o que se move"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.stalagmite_seed', 'Semente de Estalagmite', 'Stalagmite Seed', 'Semilla de estalagmita', 'Semente que faz estalagmites irromperem em um quadrado, causando 6d6 perfurante e criando terreno difícil por 1 minuto.', 'A seed erupts into stalagmites in a square, dealing 6d6 piercing damage and creating difficult terrain for 1 minute.', 'Una semilla hace brotar estalagmitas en un cuadrado, causando 6d6 perforante y creando terreno difícil durante 1 minuto.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 100, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; Manuseio; lança, usa como pedra de funda ou munição","area":"quadrado de 1,5 metro escolhido, não alvo específico","damage":"6d6 perfurante; Reflexos básico CD 23","duration":"estalagmites por 1 minuto; depois viram pó e o terreno deixa de ser difícil"},"needs_review":false}'::jsonb),
  ('item.rage_elements.earth.vital_earth', 'Terra Vital', 'Vital Earth', 'Tierra vital', 'Pó de terra vital inalado que dispensa ar e água por 24 horas e melhora Medicina para tratar seus ferimentos.', 'Inhaled vital earth removes the need for air and water for 24 hours and improves Medicine checks to treat your wounds.', 'La tierra vital inhalada elimina la necesidad de aire y agua durante 24 horas y mejora Medicina para tratar tus heridas.', 'magical', 9, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 100, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; Manuseio; inalar","duration":"24 horas sem precisar de ar ou água","medicine":"Administer First Aid e Treat Wounds não exigem kit de curandeiro e recebem +1 item em Medicina"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.ash_gown', 'Vestido de Cinzas', 'Ash Gown', 'Vestido de ceniza', 'Veste investida que concede resistência a fogo e Intimidação e incinera obstáculos e criaturas ao atravessar o campo.', 'An invested gown grants fire resistance and Intimidation and burns obstacles and creatures as you move.', 'Una prenda investida concede resistencia al fuego e Intimidación y quema obstáculos y criaturas al moverte.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 122, '{"usage":null,"effects":[],"mechanics":{"resistance":"5 fogo; +1 Intimidação","activate":"2 ações; 1/dia; Stride e Golpe","effect":"ignora e destrói terreno difícil não mágico; criaturas adjacentes durante o movimento sofrem 2d6 fogo; Reflexos básico CD 23","variant":"greater: resistência 10, +2 Intimidação, 1/10 minutos, 4d6/CD 28"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.bloodburn_censer', 'Turíbulo Queima-Sangue', 'Bloodburn Censer', 'Incensario quema sangre', 'Incensário que cria uma aura de fumaça de fogo ou veneno, causando dano persistente e enfraquecendo criaturas.', 'A censer creates a fire or poison smoke aura that deals persistent damage and weakens creatures.', 'Un incensario crea un aura de humo de fuego o veneno que causa daño persistente y debilita criaturas.', 'magical', 13, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 122, '{"usage":null,"effects":[],"mechanics":{"activate":"2 ações; 1/dia; incenso de 5 po; emanação de 6 metros; Fortitude CD 34","criticalSuccess":"sem efeito","success":"2d6 dano persistente","failure":"4d6 dano persistente e Enfraquecido 2","criticalFailure":"6d6 dano persistente e Enfraquecido 3","immunity":"1 hora"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.brazier_of_harmony', 'Braseiro da Harmonia', 'Brazier of Harmony', 'Brasero de armonía', 'Incensário que concede bônus de Diplomacia e cria uma aura de paz equivalente a calm de 3º círculo.', 'A censer grants a Diplomacy bonus and creates a peace aura equivalent to 3rd-rank calm.', 'Un incensario concede bonificación a Diplomacia y crea un aura de paz equivalente a calm de 3er rango.', 'magical', 5, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 122, '{"usage":null,"effects":[],"mechanics":{"diplomacy":"+1 item em Diplomacia enquanto segurado","activate":"2 ações; 1/dia; incenso de 1 pp; emanação de 6 metros","effect":"calm de 3º círculo; imunidade por 24 horas; dura até o incenso acabar"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.candle_of_inflamed_passions', 'Vela das Paixões Inflamadas', 'Candle of Inflamed Passions', 'Vela de pasiones inflamadas', 'Vela consumível que eleva emoções e impõe penalidade a salvamentos contra efeitos emocionais por 10 minutos.', 'A consumable candle heightens emotions and penalizes saves against emotion effects for 10 minutes.', 'Una vela consumible intensifica emociones y penaliza salvaciones contra efectos emocionales durante 10 minutos.', 'magical', 3, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 122, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; acender","area":"3 metros","effect":"–1 de estado em salvamentos contra efeitos emocionais; queima por 10 minutos; não pode ser reacendida"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.everburning_coal', 'Carvão Inextinguível', 'Everburning Coal', 'Carbón inextinguible', 'Carvão que concede resistência a frio, protege de ambientes frios, melhora viagens ao Plano do Fogo e cria uma muralha de brasas.', 'A coal grants cold resistance, protects from cold environments, improves travel to the Plane of Fire, and creates a wall of coals.', 'Un carbón concede resistencia al frío, protege de entornos fríos, mejora viajes al Plano del Fuego y crea un muro de brasas.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 123, '{"usage":null,"effects":[],"mechanics":{"resistance":"10 a frio; proteção contra frio moderado, severo e extremo","planarKey":"chega a 1d6×25 milhas do destino em vez de 1d10×25","activate":"3 ações; 1/dia; wall of ice com traços, dano e fraquezas trocados para fogo; frio/água evaporam seções"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.globe_of_shrouds', 'Globo de Mortalhas', 'Globe of Shrouds', 'Globo de mortajas', 'Incensário que oculta aliados e revela inimigos invisíveis dentro de uma aura de fumaça.', 'A censer conceals allies and reveals invisible enemies within a smoke aura.', 'Un incensario oculta aliados y revela enemigos invisibles dentro de un aura de humo.', 'magical', 8, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 123, '{"usage":null,"effects":[],"mechanics":{"activate":"2 ações; 1/dia; incenso de 5 po; emanação de 6 metros","allies":"aliado fica oculto e recebe +2 de estado em Furtividade","enemies":"inimigo invisível vira forma translúcida para você e aliados; não fica oculto, mas permanece oculto por concealment"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.lambent_perfume', 'Perfume Lampejante', 'Lambent Perfume', 'Perfume lambente', 'Incensário que permite novas tentativas de salvamento para superar enjoo ou aflições dentro da fumaça.', 'A censer lets creatures attempt new saves to overcome sickened or afflictions in its smoke.', 'Un incensario permite nuevas salvaciones para superar Enfermado o aflicciones dentro de su humo.', 'magical', 6, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 123, '{"usage":null,"effects":[],"mechanics":{"activate":"2 ações; 1/dia; incenso de 1 pp; emanação de 6 metros","effect":"ao fim do turno na fumaça, criatura enjoada ou com aflição tenta novo salvamento; escolhe uma; imunidade 24 horas para essa aflição"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.obsidian_edge', 'Lâmina de Obsidiana', 'Obsidian Edge', 'Filo de obsidiana', 'Gun sword +1 striking que causa dano de fogo adicional e explode estilhaços de magma após um Golpe à distância bem-sucedido.', 'A +1 striking gun sword deals extra fire damage and erupts magma shards after a successful ranged Strike.', 'Una gun sword +1 striking causa daño de fuego adicional y libera astillas de magma tras un Golpe a distancia exitoso.', 'magical', 6, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 123, '{"usage":null,"effects":[],"mechanics":{"weapon":"+1 striking gun sword; +1 fogo por Golpe","activate":"1 ação; 1/10 minutos; ação anterior foi Golpe à distância bem-sucedido","effect":"emanação de 4,5 metros; 2d6 fogo + 2d6 perfurante; Reflexos básico CD 20","variants":"greater 3d6 fogo + 2d6/CD 25; major 4d6 + 3d6/CD 29; true 5d6 + 4d6/CD 38"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.rhyton_of_the_radiant_ifrit', 'Ríton do Ifrit Radiante', 'Rhyton of the Radiant Ifrit', 'Ritón del ifrit radiante', 'Rhyton que se enche de bebida, concede bônus social e permite a um ifrit emitir comando de 6º círculo contra inimigos.', 'A rhyton refills with drinks, grants a social bonus, and lets an ifrit issue 6th-rank command against enemies.', 'Un rhyton se rellena de bebidas, concede bonificación social y permite que un ifrit use command de 6º rango contra enemigos.', 'magical', 14, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 124, '{"usage":null,"effects":[],"mechanics":{"drink":"bottomless stein; nome sussurrado traz bebida favorita do shuyookh de qualquer plano","toast":"1 ação; +2 item em Dissimulação, Diplomacia ou Intimidação contra criaturas por 1 hora","command":"2 ações; 1/dia; command de 6º círculo contra todos os hostis no alcance; falha também causa Fatigado"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.scalding_gauntlets', 'Manoplas Escaldantes', 'Scalding Gauntlets', 'Guanteletes hirvientes', 'Manoplas espinhosas striking que causam fogo persistente e enjoo ao agarrar ou restringir uma criatura.', 'Striking spiked gauntlets deal persistent fire and sickened when you Grab or restrain a creature.', 'Unos guanteletes con púas striking causan fuego persistente y Enfermado al Agarrar o restringir.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 124, '{"usage":null,"effects":[],"mechanics":{"weapon":"+2 striking spiked gauntlets","trigger":"criatura agarrada ou restringida","save":"Fortitude CD 26","effect":"2d6 fogo persistente e Enjoado 1; imunidade ao Enjoado por 1 hora","variants":"greater CD 28; major CD 32 e 3d6; true CD 36 e 4d6"},"needs_review":false}'::jsonb)
insert into public.catalog_items (id, name_pt, name_en, name_es, description_pt, description_en, description_es, item_category, level, price_gp, bulk, hands, traits, rarity, ruleset, source_book, source_page, data)
values
  ('item.rage_elements.fire.smoke_veil', 'Véu de Fumaça', 'Smoke Veil', 'Velo de humo', 'Véu investido que facilita disfarces e permite Demoralizar visualmente após causar dano de fogo.', 'An invested veil facilitates disguises and enables visual Demoralize after dealing fire damage.', 'Un velo investido facilita disfraces y permite Desmoralizar visualmente tras causar daño de fuego.', 'magical', 3, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 124, '{"usage":null,"effects":[],"mechanics":{"disguise":"pode Impersonate sem kit; cria disfarce em 1 minuto; +1 item; kit e tempo completo para cosméticos ou pessoa específica","activate":"1 ação; após causar fogo a alvo visível a até 9 metros","effect":"teste de Intimidação para Demoralizar; perde traço auditivo, ganha visual e sem penalidade por idioma"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.sparkshade_parasol', 'Sombrinha Fagulhante', 'Sparkshade Parasol', 'Parasol de chispas', 'Sombrinha investida que protege contra calor e fogo e pode devolver uma linha de 9 metros com 10d6 de fogo.', 'An invested parasol protects from heat and fire and can release a 30-foot line for 10d6 fire damage.', 'Una sombrilla investida protege del calor y fuego y puede liberar una línea de 9 metros con 10d6 de fuego.', 'magical', 11, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 124, '{"usage":null,"effects":[],"mechanics":{"resistance":"10 fogo; proteção contra calor ambiental moderado, severo e extremo","protection":"reação; 1/10 minutos; recebe resistência 20 contra o efeito de fogo","pyrotechnics":"2 ações; enquanto carga está ativa; linha de 9 metros; 10d6 fogo; Reflexos básico CD 28"},"needs_review":false}'::jsonb),
  ('item.rage_elements.fire.thawing_candle', 'Vela do Degelo', 'Thawing Candle', 'Vela del deshielo', 'Vela consumível que concede resistência a frio e permite encerrar dano persistente de frio por 10 minutos.', 'A consumable candle grants cold resistance and lets creatures end persistent cold damage for 10 minutes.', 'Una vela consumible concede resistencia al frío y permite terminar daño persistente de frío durante 10 minutos.', 'magical', 8, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 125, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; acender","area":"3 metros; queima por 10 minutos","effect":"resistência 10 a frio; quem tem dano persistente de frio tenta CD 15 para encerrá-lo ao entrar ou estar na área; uma vez por criatura"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.curious_teardrop', 'Gota Curiosa', 'Curious Teardrop', 'Gota curiosa', 'Gota inteligente de metal líquido que se comunica por telepatia, conjura magias e reflete efeitos emocionais ou de metal.', 'An intelligent liquid-metal teardrop communicates telepathically, casts spells, and reflects emotion or metal effects.', 'Una gota inteligente de metal líquido se comunica telepáticamente, lanza conjuros y refleja efectos emocionales o de metal.', 'magical', 16, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 146, '{"usage":null,"effects":[],"mechanics":{"senses":"visão precisa 18 metros e audição imprecisa 9 metros","communication":"telepatia em Comum e Talican","request":"2 ações; 1/dia; curse of lost time, ferrous form ou elemental form de 7º círculo (metal)","reflect":"reação contra efeito emocional ou de metal; +4 status no salvamento e counteract +36, refletindo cópia ao originador"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.ferrofluid_urchin', 'Ouriço Ferrofluido', 'Ferrofluid Urchin', 'Erizo ferrofluido', 'Talismã que se fixa a armadura metálica e concede resistência ao dano físico desencadeador.', 'A talisman attaches to metal armor and grants resistance to the triggering physical damage.', 'Un talismán se adhiere a armadura metálica y concede resistencia al daño físico desencadenante.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 146, '{"usage":null,"effects":[],"mechanics":{"usage":"afixado a armadura média ou pesada de metal","trigger":"você sofre dano físico","prerequisite":"efeito de especialização da armadura","activate":"ação livre; Concentração","variants":"menor resistência 3; moderada 6; maior 10"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.malleable', 'Maleável', 'Malleable', 'Maleable', 'Runa de armadura que permite trocar o grupo de especialização da armadura, mantendo materiais e runas aplicáveis.', 'An armor rune lets you change the armor''s specialization group while retaining materials and applicable runes.', 'Una runa de armadura permite cambiar el grupo de especialización manteniendo materiales y runas aplicables.', 'magical', 9, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 146, '{"usage":null,"effects":[],"mechanics":{"usage":"gravada em armadura média ou pesada de metal","activate":"1 ação; Manuseio","effect":"troca o grupo de especialização; runas incompatíveis ficam suprimidas até nova composição"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.morphing_weapon', 'Arma Mutável', 'Morphing Weapon', 'Arma cambiante', 'Arma +1 striking shifting que assume formas metálicas e pode aumentar alcance, trocar tipo de dano, Desarmar ou causar dano extra.', 'A +1 striking shifting weapon takes metal forms and can increase reach, change damage type, Disarm, or deal extra damage.', 'Un arma +1 striking shifting adopta formas metálicas y puede aumentar alcance, cambiar daño, Desarmar o causar daño adicional.', 'magical', 7, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 146, '{"usage":null,"effects":[],"mechanics":{"base":"+1 striking shifting; Volume varia; 1 ou 2 mãos","activate":"1 ação; 1/10 minutos; Concentração","benefits":"Reach: +1,5 metro de alcance; Shift: contundente, perfurante ou cortante; Take: reação após acerto para Desarmar ou Roubar; Weigh: bônus de dano igual aos dados da arma"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.resonant_guitar', 'Guitarra Ressonante', 'Resonant Guitar', 'Guitarra resonante', 'Instrumento virtuoso que melhora Performance, facilita viagens ao Plano do Metal, concede runa thundering e protege contra Golpes corpo a corpo.', 'A virtuoso instrument improves Performance, aids travel to the Plane of Metal, grants thundering, and protects against melee Strikes.', 'Un instrumento virtuoso mejora Interpretación, facilita viajes al Plano del Metal, concede thundering y protege contra Golpes cuerpo a cuerpo.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 147, '{"usage":null,"effects":[],"mechanics":{"performance":"+2 item em Performance","planarKey":"chega a 1d6×25 milhas do destino em vez de 1d10×25","thunder":"1 minuto; 1/dia; arma metálica a até 18 metros recebe thundering por 1 hora","protection":"reação; 1/dia; aliado a até 9 metros recebe +2 AC; se o ataque acertar, atacante sofre 3d10 sônico"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.rustbringer', 'Portador de Ferrugem', 'Rustbringer', 'Portaóxido', 'Mangual +1 striking corrosivo com deadly d10 contra criaturas metálicas e reação que danifica uma arma metálica desarmada.', 'A +1 striking corrosive flail gains deadly d10 against metal creatures and damages a disarmed metal weapon.', 'Un mangual +1 striking corrosivo obtiene deadly d10 contra criaturas metálicas y daña un arma metálica desarmada.', 'magical', 10, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 147, '{"usage":null,"effects":[],"mechanics":{"weapon":"+1 striking corrosive flail; deadly d10 contra criatura principalmente metálica","activate":"reação após sucesso crítico em Desarmar arma metálica","effect":"arma desarmada sofre 2d6 dano, ignorando Dureza","variant":"greater: +3 greater striking greater corrosive; 4d6 ácido"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.silver_snake_cane', 'Bengala Serpente de Prata', 'Silver Snake Cane', 'Bastón serpiente de plata', 'Bengala que armazena elixir ou veneno e se transforma em espada-cajado de prata ou víbora gigante.', 'A cane stores an elixir or poison and transforms into a silver sword cane or giant viper.', 'Un bastón almacena un elixir o veneno y se transforma en espada de plata o víbora gigante.', 'magical', 6, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 147, '{"usage":null,"effects":[],"mechanics":{"storage":"1 minuto; guarda um elixir ou veneno ingerido/de ferimento; expira em 24 horas ou ao substituir","sword":"1 ação; Concentração e Polimorfia; +1 striking silver sword cane por 10 minutos; aplica veneno de ferimento","serum":"1 ação; 1/dia; morde alvo voluntário, 1 perfurante e injeta o item","viper":"1 ação; requer zuhra; transforma-se em víbora gigante de prata obediente"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.spellsap_grenade', 'Granada Drena-Feitiço', 'Spellsap Grenade', 'Granada drenaconjuros', 'Bomba alquímica que causa dano cortante e pode fazer um conjurador perder aleatoriamente uma magia ou espaço entre seus três maiores círculos.', 'An alchemical bomb deals slashing damage and can randomly make a spellcaster lose a spell or slot among their three highest ranks.', 'Una bomba alquímica causa daño cortante y puede hacer que un lanzador pierda un conjuro o espacio entre sus tres rangos más altos.', 'magical', 12, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 147, '{"usage":null,"effects":[],"mechanics":{"activate":"1 ação; Golpe","moderate":"+2 item; 3d4 cortante + 3 splash; Vontade CD 30","greater":"+3 item; 4d4 cortante + 4 splash; Vontade CD 38","effect":"em acerto contra conjurador preparado ou espontâneo, falha no salvamento perde uma magia/espaço aleatório dos três maiores círculos"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.spiny_lodestone', 'Pedra-Ímã Espinhosa', 'Spiny Lodestone', 'Piedra imán espinosa', 'Spellheart que conjura needle darts e, conforme seja afixado a armadura ou arma, concede Atletismo/resistência ou dano perfurante extra.', 'A spellheart casts needle darts and grants Athletics/resistance on armor or extra piercing damage on a weapon.', 'Un spellheart lanza needle darts y concede Atletismo/resistencia en armadura o daño perforante adicional en arma.', 'magical', 4, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 147, '{"usage":null,"effects":[],"mechanics":{"usage":"afixado a armadura ou arma metálica","activation":"Conjurar uma Magia; needle darts; ataque +8, CD 18","armor":"+1 item em Atletismo e resistência 2 a dano não letal","weapon":"após conjurar, Golpes causam +1d4 perfurante até fim do próximo turno","variants":"greater: resistência 5, +1d6, ataque +14/CD 24; major: +2 Atletismo, resistência 10, +1d8, ataque +19/CD 29 e magias adicionais"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.staff_of_metal', 'Bastão de Metal', 'Staff of Metal', 'Bastón de metal', 'Cajado que concede bônus para atacar criaturas ou armaduras metálicas e oferece magias de metal, magnetismo e ferrugem.', 'A staff grants an attack bonus against metal creatures or armor and provides metal, magnetism, and rust spells.', 'Un bastón concede bonificación para atacar criaturas o armaduras metálicas y ofrece conjuros de metal, magnetismo y óxido.', 'magical', 6, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 147, '{"usage":null,"effects":[],"mechanics":{"usage":"segurado; cajado de metal","attack":"+1 circunstancial no ataque contra alvo de armadura metálica ou principalmente metálico","spells":"detect metal; conductive weapon; shielded arm; magnetic attraction/repulsion; variantes incluem magnetic acceleration, noxious metals, mercurial stride, rust cloud, field of razors e impaling spike"},"needs_review":false}'::jsonb),
  ('item.rage_elements.metal.zuhras_gloves', 'Luvas de Zuhra', 'Zuhra''s Gloves', 'Guantes de Zuhra', 'Luvas investidas que protegem itens contra Desarmar e canalizam arma storm ou muralha de metal uma vez por dia.', 'Invested gloves protect held items from Disarm and channel weapon storm or a wall of metal once per day.', 'Unos guantes investidos protegen objetos contra Desarmar y canalizan weapon storm o un muro de metal una vez al día.', 'magical', 13, 0, 'L', NULL, ARRAY[]::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 148, '{"usage":null,"effects":[],"mechanics":{"reflex":"+3 item na CD de Reflexos contra tentativas de Desarmar item segurado","activate":"2 ações; 1/dia; Concentração e Manuseio; arma principalmente metálica","offense":"weapon storm de 6º círculo replicando a arma","defense":"wall of metal; perde o bônus de Reflexos até a barreira terminar; pode Dissipar","saveDC":"30"},"needs_review":false}'::jsonb),
  ('item.pc2.smoke_ball', 'Bola de Fumaça', 'Smoke Ball', 'Bola de humo', 'Cria uma explosão de fumaça densa: criaturas na área ficam ocultadas, e a fumaça dura 1 minuto ou até ser dispersada por ventos fortes. Raio de 1,5 m; a versão maior tem raio de 3 m.', 'Creates a burst of dense smoke: creatures in the area are concealed, and the smoke lasts 1 minute or until dispersed by strong winds. The radius is 1.5 meters; the greater version has a 3-meter radius.', 'Crea una explosión de humo denso: las criaturas en el área quedan ocultas, y el humo dura 1 minuto o hasta que lo dispersen vientos fuertes. El radio es de 1,5 metros; la versión mayor tiene un radio de 3 metros.', 'compendio', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"usage":null,"effects":[],"mechanics":{"activation":"Interact","area":"burst","radius":"1.5 m","greaterRadius":"3 m","duration":"1 minute or until strong winds disperse it","conditions":["concealed"]},"needs_review":false}'::jsonb),
  ('item.pc2.horned_arrow', 'Flecha de Galhada', 'Horned Arrow', 'Flecha de astas', 'Ao atingir, galhadas luminosas prendem o alvo em uma superfície após um salvamento de Reflexos.', 'On a hit, luminous antlers pin the target to a surface after a Reflex save.', 'Al impactar, unas astas luminosas fijan al objetivo a una superficie tras una salvación de Reflejos.', 'compendio', 2, 7, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.storm_arrow', 'Flecha de Tempestade', 'Storm Arrow', 'Flecha de tormenta', 'Ao atingir, causa 3d12 de dano de eletricidade e exige um salvamento de Reflexos.', 'On a hit, it deals 3d12 electricity damage and requires a Reflex save.', 'Al impactar, causa 3d12 de daño eléctrico y requiere una salvación de Reflejos.', 'compendio', 9, 130, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.viper_arrow', 'Flecha de Víbora', 'Viper Arrow', 'Flecha de víbora', 'Ao atingir, transforma-se em uma víbora convocada que afeta o alvo com seu veneno.', 'On a hit, it transforms into a summoned viper whose poison affects the target.', 'Al impactar, se transforma en una víbora convocada cuyo veneno afecta al objetivo.', 'compendio', 4, 17, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.sleep_arrow', 'Flecha do Sono', 'Sleep Arrow', 'Flecha del sueño', 'Não causa dano; uma criatura viva atingida faz um salvamento de Vontade ou fica letárgica e lenta.', 'It deals no damage; a living creature hit must make a Will save or become lethargic and slowed.', 'No causa daño; una criatura viva impactada debe hacer una salvación de Voluntad o queda aletargada y ralentizada.', 'compendio', 3, 10, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 301, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.frightening_ammunition', 'Munição Aterrorizante', 'Frightening Ammunition', 'Munición aterrorizante', 'Ao ferir, enche a mente do alvo com visões terríveis e pode deixá-lo assustado.', 'On a hit, it fills the target''s mind with terrifying visions and can make it frightened.', 'Al herir, llena la mente del objetivo de visiones aterradoras y puede asustarlo.', 'compendio', 6, 50, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.freezing_ammunition', 'Munição Congelante', 'Freezing Ammunition', 'Munición congelante', 'Ao atingir, exige um salvamento de Fortitude ou deixa o alvo lento pelo frio intenso.', 'On a hit, it requires a Fortitude save or slows the target from intense cold.', 'Al impactar, requiere una salvación de Fortaleza o ralentiza al objetivo por el frío intenso.', 'compendio', 5, 25, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.corrosive_ammunition', 'Munição Corrosiva', 'Corrosive Ammunition', 'Munición corrosiva', 'Ao atingir, causa 1d8 de dano de ácido persistente que ignora a Dureza da armadura.', 'On a hit, it deals 1d8 persistent acid damage that ignores armor Hardness.', 'Al impactar, causa 1d8 de daño de ácido persistente que ignora la Dureza de la armadura.', 'compendio', 7, 70, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.disintegration_bolt', 'Virote de Desintegração', 'Disintegration Bolt', 'Virote de desintegración', 'Ao atingir, afeta o alvo como a magia desintegrar após um salvamento de Fortitude.', 'On a hit, it affects the target like the disintegrate spell after a Fortitude save.', 'Al impactar, afecta al objetivo como el conjuro desintegrar tras una salvación de Fortaleza.', 'compendio', 15, 1300, '-', NULL, ARRAY['Consumível', 'Mágico', 'Munição']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 302, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.urgent_escape_potion', 'Poção de Fuga Urgente', 'Urgent Escape Potion', 'Poción de fuga urgente', 'Ao beber, fica fugindo por 1 minuto, recebe +12 metros nas Velocidades e Anda imediatamente.', 'When consumed, you flee for 1 minute, gain a +12-meter status bonus to Speeds, and immediately Stride.', 'Al beberla, huyes durante 1 minuto, obtienes +12 metros a las Velocidades y Avanzas inmediatamente.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível', 'Mágico', 'Poção']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 304, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.retaliation_potion_minimum', 'Poção da Retaliação Mínima', 'Retaliation Potion (Minimum)', 'Poción de represalia mínima', 'Por 1 minuto, uma aura causa 1 de dano de ácido, eletricidade, fogo ou frio a quem tocar você.', 'For 1 minute, an aura deals 1 acid, electricity, fire, or cold damage to creatures that touch you.', 'Durante 1 minuto, una aura causa 1 de daño de ácido, electricidad, fuego o frío a quienes te toquen.', 'compendio', 1, 4, 'L', NULL, ARRAY['Consumível', 'Mágico', 'Poção']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 304, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.ration_tonic', 'Tônico de Ração', 'Ration Tonic', 'Tónico de ración', 'Ao beber, você fica magicamente alimentado com o equivalente a um dia de comida e água.', 'When consumed, you become magically nourished with the equivalent of one day''s food and water.', 'Al beberlo, quedas alimentado mágicamente con el equivalente a un día de comida y agua.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível', 'Mágico', 'Poção']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 304, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.snake_oil', 'Óleo de Cobra', 'Snake Oil', 'Aceite de serpiente', 'Aplicado a um ferimento ou sintoma visível, faz o sintoma desaparecer por 1 hora e impede que a criatura sinta os efeitos da condição, embora eles permaneçam. Percepção CD 17 com Buscar detecta a farsa.', 'Applied to a wound or visible symptom, it makes the symptom disappear for 1 hour and prevents the creature from feeling the condition''s effects, although they remain. Perception DC 17 with Seek detects the deception.', 'Aplicado a una herida o síntoma visible, hace desaparecer el síntoma durante 1 hora y evita que la criatura sienta los efectos de la condición, aunque permanecen. Percepción CD 17 con Buscar detecta el engaño.', 'compendio', 1, 2, 'L', NULL, ARRAY['Alquímico', 'Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"usage":null,"effects":[],"mechanics":{"activation":"Interact","duration":"1 hour","perceptionDC":17,"detectionAction":"Seek","effect":"visible symptom disappears and condition effects are not felt; condition remains"},"needs_review":false}'::jsonb),
  ('item.pc2.ghost_ink', 'Tinta Fantasma', 'Ghost Ink', 'Tinta fantasmal', 'Fica transparente por 1 minuto após aplicada e brilha em vermelho quando exposta ao calor. O criador pode escolher luz solar, luz estelar, luz mágica ou luz alquímica sem calor como método de revelação.', 'It becomes transparent for 1 minute after application and glows red when exposed to heat. The creator can choose sunlight, starlight, magical light, or heatless alchemical light as the revealing method.', 'Se vuelve transparente durante 1 minuto tras aplicarla y brilla en rojo al exponerse al calor. El creador puede elegir luz solar, luz estelar, luz mágica o luz alquímica sin calor como método de revelación.', 'compendio', 1, 3, 'L', NULL, ARRAY['Alquímico', 'Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 296, '{"usage":null,"effects":[],"mechanics":{"activation":"Interact","duration":"1 minute","writingCapacity":"1 page per bottle","detectionPerceptionDC":25,"revealMethods":["sunlight","starlight","magic light","heatless alchemical light"]},"needs_review":false}'::jsonb),
  ('item.pc2.mystic_shield_paste', 'Pasta de Escudo Místico', 'Mystic Armor Paste', 'Pasta de escudo místico', 'Reforça temporariamente uma armadura ou escudo contra um tipo de energia escolhido.', 'Temporarily reinforces armor or a shield against a chosen energy type.', 'Refuerza temporalmente una armadura o escudo contra un tipo de energía elegido.', 'compendio', 2, 4, 'L', NULL, ARRAY['Alquímico', 'Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 303, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.revelation_oil', 'Óleo da Revelação', 'Oil of Revelation', 'Aceite de revelación', 'Revela marcas, escritas e propriedades ocultas em uma superfície tratada.', 'Reveals hidden marks, writing, and properties on a treated surface.', 'Revela marcas, escrituras y propiedades ocultas en una superficie tratada.', 'compendio', 5, 25, 'L', NULL, ARRAY['Alquímico', 'Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 303, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.cunning_salve', 'Unguento Ardiloso', 'Cunning Salve', 'Ungüento astuto', 'Unguento mágico que melhora temporariamente uma tentativa de Enganação ou disfarce.', 'A magic salve that temporarily improves a Deception or disguise attempt.', 'Un ungüento mágico que mejora temporalmente una prueba de Engaño o disfraz.', 'compendio', 4, 25, 'L', NULL, ARRAY['Alquímico', 'Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 303, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.minor_antidote', 'Antídoto Menor', 'Lesser Antidote', 'Antídoto menor', 'Elixir alquímico que auxilia contra venenos; consulte a descrição completa para o teste e a duração.', 'Alchemical elixir that assists against poisons; see the full entry for the check and duration.', 'Elixir alquímico que ayuda contra venenos; consulta la entrada completa para la prueba y duración.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 286, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.minor_antiplague', 'Antipeste Menor', 'Lesser Antiplague', 'Antipeste menor', 'Elixir alquímico que concede +2 de bônus de item em testes contra doenças por 24 horas.', 'Alchemical elixir granting +2 item bonus against disease for 24 hours.', 'Elixir alquímico que otorga +2 contra enfermedades durante 24 horas.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 286, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.alarm_snare', 'Arapuca de Alarme', 'Alarm Snare', 'Trampa de alarma', 'Arapuca que emite um alerta quando uma criatura entra na área preparada.', 'A snare that emits an alert when a creature enters the prepared area.', 'Una trampa que emite una alerta cuando una criatura entra en el área preparada.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 298, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.spike_snare', 'Arapuca de Espinho', 'Spike Snare', 'Trampa de púas', 'Arapuca que fere e pode impedir o movimento de uma criatura que a aciona.', 'A snare that injures and can impede a creature that triggers it.', 'Una trampa que hiere y puede impedir el movimiento de una criatura que la activa.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 298, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.caltrop_snare', 'Arapuca de Estrepes', 'Caltrop Snare', 'Trampa de abrojos', 'Arapuca que espalha estrepes e dificulta o deslocamento na área preparada.', 'A snare that scatters caltrops and hinders movement in the prepared area.', 'Una trampa que dispersa abrojos y dificulta el movimiento en el área preparada.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 298, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.arsenic', 'Arsênico', 'Arsenic', 'Arsénico', 'Veneno ingerido com Fortitude CD 18, latência de 10 minutos e duração máxima de 5 minutos. Estágios: 1d4 de veneno e enjoado 1; 1d6 de veneno e enjoado 2; 1d8 de veneno e enjoado 3.', 'Ingested poison with Fortitude DC 18, a 10-minute onset, and a 5-minute maximum duration. Stages: 1d4 poison and sickened 1; 1d6 poison and sickened 2; 1d8 poison and sickened 3.', 'Veneno ingerido con Fortaleza CD 18, latencia de 10 minutos y duración máxima de 5 minutos. Etapas: 1d4 de veneno y enfermo 1; 1d6 de veneno y enfermo 2; 1d8 de veneno y enfermo 3.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":18,"onset":"10 minutes","maximumDuration":"5 minutes","stages":["1d4 poison + sickened 1","1d6 poison + sickened 2","1d8 poison + sickened 3"]},"needs_review":false}'::jsonb),
  ('item.pc2.bright_rod', 'Bastão Brilhante', 'Bright Rod', 'Bastón brillante', 'Ferramenta alquímica que fornece iluminação intensa por sua duração.', 'An alchemical tool that provides bright illumination for its duration.', 'Herramienta alquímica que proporciona iluminación intensa durante su duración.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.silver_lotion', 'Loção de Prata', 'Silver Lotion', 'Loción de plata', 'Loção alquímica aplicada a uma criatura ou objeto para interagir com efeitos de prata.', 'An alchemical lotion applied to a creature or object to interact with silver effects.', 'Loción alquímica aplicada a una criatura u objeto para interactuar con efectos de plata.', 'compendio', 2, 6, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.belladonna', 'Beladona', 'Belladonna', 'Belladona', 'Veneno ingerido com Fortitude CD 19, latência de 10 minutos e duração máxima de 30 minutos. Estágios: ofuscado por 10 minutos; 1d6 de veneno e enjoado 1 por 10 minutos; 1d6 de veneno, confuso e enjoado 1 por 1 minuto.', 'Ingested poison with Fortitude DC 19, a 10-minute onset, and a 30-minute maximum duration. Stages: dazzled for 10 minutes; 1d6 poison and sickened 1 for 10 minutes; 1d6 poison, confused, and sickened 1 for 1 minute.', 'Veneno ingerido con Fortaleza CD 19, latencia de 10 minutos y duración máxima de 30 minutos. Etapas: deslumbrado durante 10 minutos; 1d6 de veneno y enfermo 1 durante 10 minutos; 1d6 de veneno, confundido y enfermo 1 durante 1 minuto.', 'compendio', 2, 5, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":19,"onset":"10 minutes","maximumDuration":"30 minutes","stages":["dazzled 10 minutes","1d6 poison + sickened 1 for 10 minutes","1d6 poison + confused + sickened 1 for 1 minute"]},"needs_review":false}'::jsonb),
  ('item.pc2.hunters_bane', 'Ruína do Caçador', 'Hunter''s Bane', 'Ruina del cazador', 'Talismã consumível que auxilia contra uma criatura escolhida como presa.', 'A consumable talisman that assists against a creature chosen as prey.', 'Talismán consumible que ayuda contra una criatura elegida como presa.', 'compendio', 2, 6, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 305, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.minor_glue_bomb', 'Bomba de Cola Menor', 'Lesser Glue Bomb', 'Bomba de pegamento menor', 'Bomba alquímica que deixa uma área ou alvo pegajoso; CD e duração devem ser conferidas no livro.', 'Alchemical bomb that makes an area or target sticky; check the book for DC and duration.', 'Bomba alquímica que vuelve pegajosa un área o criatura; verifica CD y duración en el libro.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 283, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
