  ('item.pc2.minor_ghost_charge', 'Carga Fantasma Menor', 'Lesser Ghost Charge', 'Carga fantasmal menor', 'Bomba alquímica com efeito especialmente útil contra criaturas incorpóreas.', 'Alchemical bomb with an effect especially useful against incorporeal creatures.', 'Bomba alquímica con un efecto especialmente útil contra criaturas incorpóreas.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 284, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.forensic_dye', 'Corante Forense', 'Forensic Dye', 'Tinte forense', 'Ao receber uma pequena quantidade de outro composto ou material, como sangue ou lama, transforma-se rapidamente em substância marrom-avermelhada e depois volta a ficar transparente.', 'When given a small amount of another compound or material, such as blood or mud, it quickly turns brown-red and then becomes clear again.', 'Al añadir una pequeña cantidad de otro compuesto o material, como sangre o barro, se vuelve rápidamente marrón rojizo y luego vuelve a ser transparente.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"usage":null,"effects":[],"mechanics":{"activation":"Interact","triggerMaterialExamples":["blood","mud"],"result":"brief brown-red coloration, then clear"},"needs_review":false}'::jsonb),
