  ('item.pc2.minor_alchemical_fire', 'Fogo Alquímico Menor', 'Lesser Alchemist''s Fire', 'Fuego alquímico menor', 'Bomba alquímica que causa dano de fogo e pode iniciar combustão persistente.', 'Alchemical bomb that deals fire damage and can start persistent combustion.', 'Bomba alquímica que causa daño de fuego y puede iniciar combustión persistente.', 'compendio', 1, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 284, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
