  ('item.pc2.giant_centipede_venom', 'Veneno de Centopeia Gigante', 'Giant Centipede Venom', 'Veneno de ciempiés gigante', 'Veneno de ferimento com Fortitude CD 17 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada: 1d4 de veneno; 1d4 de veneno e fatigado; 1d4 de veneno, desajeitado 1 e fatigado.', 'Injury poison with Fortitude DC 17 and a 6-round maximum duration. Each stage lasts 1 round: 1d4 poison; 1d4 poison and fatigued; 1d4 poison, clumsy 1, and fatigued.', 'Veneno de herida con Fortaleza CD 17 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto: 1d4 de veneno; 1d4 de veneno y fatigado; 1d4 de veneno, torpe 1 y fatigado.', 'compendio', 1, 4, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":17,"maximumDuration":"6 rounds","stageDuration":"1 round","stages":["1d4 poison","1d4 poison + fatigued","1d4 poison + clumsy 1 + fatigued"]},"needs_review":false}'::jsonb),
  ('item.pc2.dead_weight_snare', 'Arapuca de Peso Morto', 'Deadweight Snare', 'Trampa de peso muerto', 'Arapuca que aumenta o peso do alvo e dificulta seu deslocamento quando acionada.', 'A snare that increases the target''s weight and hinders movement when triggered.', 'Trampa que aumenta el peso del objetivo y dificulta su movimiento al activarse.', 'compendio', 2, 6, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 299, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.signaling_snare', 'Arapuca Sinalizadora', 'Signaling Snare', 'Trampa señalizadora', 'Arapuca que produz um sinal audível ou visual quando uma criatura entra na área preparada.', 'A snare that produces an audible or visual signal when a creature enters the prepared area.', 'Trampa que produce una señal audible o visual cuando una criatura entra en el área preparada.', 'compendio', 2, 5, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 300, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.marking_snare', 'Arapuca de Marcar', 'Marking Snare', 'Trampa marcadora', 'Arapuca que marca a criatura atingida para facilitar seu rastreamento.', 'A snare that marks the struck creature to make tracking it easier.', 'Trampa que marca a la criatura alcanzada para facilitar su rastreo.', 'compendio', 2, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 299, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.hindering_snare', 'Arapuca Impeditiva', 'Hindering Snare', 'Trampa impeditiva', 'Arapuca que impõe uma penalidade de movimento ou cria uma obstrução ao ser acionada.', 'A snare that penalizes movement or creates an obstruction when triggered.', 'Trampa que penaliza el movimiento o crea una obstrucción al activarse.', 'compendio', 2, 3, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 300, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.lethargy_poison', 'Veneno de Letargia', 'Lethargy Poison', 'Veneno de letargo', 'Veneno de ferimento com Fortitude CD 18 e duração máxima de 4 horas. Os estágios causam desacelerado 1, desacelerado 1, inconsciente e, no estágio 4, inconsciente por 1d4 horas.', 'Injury poison with Fortitude DC 18 and a 4-hour maximum duration. Stages cause slowed 1, slowed 1, unconscious, and at stage 4 unconscious for 1d4 hours.', 'Veneno de herida con Fortaleza CD 18 y duración máxima de 4 horas. Las etapas causan ralentizado 1, ralentizado 1, inconsciente y, en la etapa 4, inconsciente durante 1d4 horas.', 'compendio', 2, 7, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":18,"maximumDuration":"4 hours","stages":["slowed 1 for 1 round","slowed 1 for 1 round","unconscious for 1 round","unconscious for 1d4 hours"]},"needs_review":false}'::jsonb),
  ('item.pc2.black_adder_venom', 'Veneno de Víbora Negra', 'Black Adder Venom', 'Veneno de víbora negra', 'Veneno de ferimento com Fortitude CD 18 e duração máxima de 3 rodadas. Cada estágio dura 1 rodada e causa 1d4, 1d6 ou 1d8 de dano de veneno.', 'Injury poison with Fortitude DC 18 and a 3-round maximum duration. Each stage lasts 1 round and deals 1d4, 1d6, or 1d8 poison damage.', 'Veneno de herida con Fortaleza CD 18 y duración máxima de 3 asaltos. Cada etapa dura 1 asalto e inflige 1d4, 1d6 o 1d8 de daño de veneno.', 'compendio', 2, 6, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":18,"maximumDuration":"3 rounds","stageDuration":"1 round","stages":["1d4 poison","1d6 poison","1d8 poison"]},"needs_review":false}'::jsonb),
  ('item.pc2.cytillesh_oil', 'Óleo de Cytillesh', 'Cytillesh Oil', 'Aceite de cytillesh', 'Veneno com Fortitude CD 19 e duração máxima de 4 rodadas. Cada estágio dura 1 rodada e causa 1d8, 1d10 ou 2d8 de dano de veneno.', 'Poison with Fortitude DC 19 and a 4-round maximum duration. Each stage lasts 1 round and deals 1d8, 1d10, or 2d8 poison damage.', 'Veneno con Fortaleza CD 19 y duración máxima de 4 asaltos. Cada etapa dura 1 asalto e inflige 1d8, 1d10 o 2d8 de daño de veneno.', 'compendio', 3, 10, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":19,"maximumDuration":"4 rounds","stageDuration":"1 round","stages":["1d8 poison","1d10 poison","2d8 poison"]},"needs_review":false}'::jsonb),
  ('item.pc2.grave_root', 'Raiz do Túmulo', 'Grave Root', 'Raíz de tumba', 'Veneno de ferimento com Fortitude CD 19 e duração máxima de 4 rodadas. Cada estágio dura 1 rodada: 1d8 de veneno; 1d10 de veneno e estupefato 1; 2d6 de veneno e estupefato 2.', 'Injury poison with Fortitude DC 19 and a 4-round maximum duration. Each stage lasts 1 round: 1d8 poison; 1d10 poison and stupefied 1; 2d6 poison and stupefied 2.', 'Veneno de herida con Fortaleza CD 19 y duración máxima de 4 asaltos. Cada etapa dura 1 asalto: 1d8 de veneno; 1d10 de veneno y estupefacto 1; 2d6 de veneno y estupefacto 2.', 'compendio', 3, 10, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":19,"maximumDuration":"4 rounds","stageDuration":"1 round","stages":["1d8 poison","1d10 poison + stupefied 1","2d6 poison + stupefied 2"]},"needs_review":false}'::jsonb),
  ('item.pc2.spider_venom', 'Veneno de Aranha', 'Spider Venom', 'Veneno de araña', 'Veneno de ferimento com Fortitude CD 22 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada: 1d10 de veneno e enjoado 1; 1d12 de veneno, desajeitado 1 e enjoado 2; 2d6 de veneno, desajeitado 2 e enjoado 3.', 'Injury poison with Fortitude DC 22 and a 6-round maximum duration. Each stage lasts 1 round: 1d10 poison and sickened 1; 1d12 poison, clumsy 1, and sickened 2; 2d6 poison, clumsy 2, and sickened 3.', 'Veneno de herida con Fortaleza CD 22 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto: 1d10 de veneno y enfermo 1; 1d12 de veneno, torpe 1 y enfermo 2; 2d6 de veneno, torpe 2 y enfermo 3.', 'compendio', 5, 25, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":22,"maximumDuration":"6 rounds","stageDuration":"1 round","stages":["1d10 poison + sickened 1","1d12 poison + clumsy 1 + sickened 2","2d6 poison + clumsy 2 + sickened 3"]},"needs_review":false}'::jsonb),
  ('item.pc2.giant_scorpion_venom', 'Veneno de Escorpião Gigante', 'Giant Scorpion Venom', 'Veneno de escorpión gigante', 'Veneno de ferimento com Fortitude CD 22 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada: 2d6 de veneno e enfraquecido 1; 2d8 de veneno e enfraquecido 1; 2d10 de veneno e enfraquecido 2.', 'Injury poison with Fortitude DC 22 and a 6-round maximum duration. Each stage lasts 1 round: 2d6 poison and enfeebled 1; 2d8 poison and enfeebled 1; 2d10 poison and enfeebled 2.', 'Veneno de herida con Fortaleza CD 22 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto: 2d6 de veneno y debilitado 1; 2d8 de veneno y debilitado 1; 2d10 de veneno y debilitado 2.', 'compendio', 6, 40, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":22,"maximumDuration":"6 rounds","stageDuration":"1 round","stages":["2d6 poison + enfeebled 1","2d8 poison + enfeebled 1","2d10 poison + enfeebled 2"]},"needs_review":false}'::jsonb),
  ('item.pc2.rooting_toxin', 'Toxina de Enraizamento', 'Rooting Toxin', 'Toxina de enraizamiento', 'Veneno de contato com Fortitude CD 26, latência de 1 minuto e duração máxima de 6 minutos. Os estágios causam desajeitado 1/2/3 e penalidade de 3/6/9 metros em todas as Velocidades por 1 minuto.', 'Contact poison with Fortitude DC 26, a 1-minute onset, and a 6-minute maximum duration. Stages cause clumsy 1/2/3 and a 10/20/30-foot penalty to all Speeds for 1 minute.', 'Veneno de contacto con Fortaleza CD 26, latencia de 1 minuto y duración máxima de 6 minutos. Las etapas causan torpe 1/2/3 y una penalización de 3/6/9 metros a todas las Velocidades durante 1 minuto.', 'compendio', 7, 55, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":26,"onset":"1 minute","maximumDuration":"6 minutes","stageDuration":"1 minute","stages":["clumsy 1 + -3 m all Speeds","clumsy 2 + -6 m all Speeds","clumsy 3 + -9 m all Speeds"]},"needs_review":false}'::jsonb),
  ('item.pc2.nettleseed_residue', 'Resíduo de Urtiga', 'Nettleweed Residue', 'Residuo de ortiga', 'Veneno de contato com Fortitude CD 27, latência de 1 minuto e duração máxima de 6 minutos. Cada estágio dura 1 minuto e causa 3d6, 4d6 ou 6d6 de dano de veneno.', 'Contact poison with Fortitude DC 27, a 1-minute onset, and a 6-minute maximum duration. Each stage lasts 1 minute and deals 3d6, 4d6, or 6d6 poison damage.', 'Veneno de contacto con Fortaleza CD 27, latencia de 1 minuto y duración máxima de 6 minutos. Cada etapa dura 1 minuto e inflige 3d6, 4d6 o 6d6 de daño de veneno.', 'compendio', 8, 75, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":27,"onset":"1 minute","maximumDuration":"6 minutes","stageDuration":"1 minute","stages":["3d6 poison","4d6 poison","6d6 poison"]},"needs_review":false}'::jsonb),
  ('item.pc2.wyvern_poison', 'Veneno de Wyvern', 'Wyvern Poison', 'Veneno de wyvern', 'Veneno de ferimento com Fortitude CD 26 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada e causa 3d6, 3d8 ou 3d10 de dano de veneno.', 'Injury poison with Fortitude DC 26 and a 6-round maximum duration. Each stage lasts 1 round and deals 3d6, 3d8, or 3d10 poison damage.', 'Veneno de herida con Fortaleza CD 26 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto e inflige 3d6, 3d8 o 3d10 de daño de veneno.', 'compendio', 8, 80, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":26,"maximumDuration":"6 rounds","stageDuration":"1 round","stages":["3d6 poison","3d8 poison","3d10 poison"]},"needs_review":false}'::jsonb),
  ('item.pc2.weakening_powder', 'Pó Debilitante', 'Weakening Powder', 'Polvo debilitante', 'Veneno ingerido com Fortitude CD 28, latência de 10 minutos e duração máxima de 6 minutos. Os estágios causam fatigado; depois 5d6 de veneno e fatigado; por fim 6d6 de veneno, fatigado e paralisado.', 'Ingested poison with Fortitude DC 28, a 10-minute onset, and a 6-minute maximum duration. Stages cause fatigued; then 5d6 poison and fatigued; finally 6d6 poison, fatigued, and paralyzed.', 'Veneno ingerido con Fortaleza CD 28, latencia de 10 minutos y duración máxima de 6 minutos. Las etapas causan fatigado; luego 5d6 de veneno y fatigado; finalmente 6d6 de veneno, fatigado y paralizado.', 'compendio', 9, 110, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":28,"onset":"10 minutes","maximumDuration":"6 minutes","stageDuration":"1 minute","stages":["fatigued","5d6 poison + fatigued","6d6 poison + fatigued + paralyzed"]},"needs_review":false}'::jsonb),
  ('item.pc2.spider_root', 'Raiz de Aranha', 'Spider Root', 'Raíz de araña', 'Veneno de contato com Fortitude CD 28, latência de 1 minuto e duração máxima de 6 minutos. Cada estágio dura 1 minuto e causa 3d6/4d6/6d6 de veneno e desajeitado 1/2/3.', 'Contact poison with Fortitude DC 28, a 1-minute onset, and a 6-minute maximum duration. Each stage lasts 1 minute and deals 3d6/4d6/6d6 poison damage with clumsy 1/2/3.', 'Veneno de contacto con Fortaleza CD 28, latencia de 1 minuto y duración máxima de 6 minutos. Cada etapa dura 1 minuto e inflige 3d6/4d6/6d6 de veneno con torpe 1/2/3.', 'compendio', 9, 110, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":28,"onset":"1 minute","maximumDuration":"6 minutes","stageDuration":"1 minute","stages":["3d6 poison + clumsy 1","4d6 poison + clumsy 2","6d6 poison + clumsy 3"]},"needs_review":false}'::jsonb),
  ('item.pc2.aconite', 'Acônito', 'Aconite', 'Acónito', 'Veneno ingerido com Fortitude CD 30, latência de 10 minutos e duração máxima de 6 minutos. Estágios: 3d10, 4d10 ou 5d10 de dano de veneno por 1 minuto; sobreviver ao estágio 3 cura imediatamente a maldição de um teriantropo.', 'Ingested poison with Fortitude DC 30, a 10-minute onset, and a 6-minute maximum duration. Stages deal 3d10, 4d10, or 5d10 poison damage for 1 minute; surviving stage 3 immediately cures a lycanthrope curse.', 'Veneno ingerido con Fortaleza CD 30, latencia de 10 minutos y duración máxima de 6 minutos. Las etapas infligen 3d10, 4d10 o 5d10 de daño de veneno durante 1 minuto; sobrevivir a la etapa 3 cura inmediatamente la maldición de un licántropo.', 'compendio', 10, 155, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":30,"onset":"10 minutes","maximumDuration":"6 minutes","stageDuration":"1 minute","stages":["3d10 poison","4d10 poison","5d10 poison"],"special":"surviving stage 3 cures a lycanthrope curse"},"needs_review":false}'::jsonb),
  ('item.pc2.draining_shadow', 'Sombra Desgastante', 'Draining Shadow', 'Sombra agotadora', 'Veneno de ferimento CD 26; inflige dano de veneno e drena a vitalidade máxima.', 'Injury poison DC 26; inflicts poison damage and drains maximum vitality.', 'Veneno de herida CD 26; causa daño de veneno y drena la vitalidad máxima.', 'compendio', 10, 160, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.black_lotus_extract', 'Extrato de Lótus Negra', 'Black Lotus Extract', 'Extracto de loto negro', 'Veneno ingerido com Fortitude CD 42, latência de 1 minuto e duração máxima de 6 rodadas. Estágios: 13d6, 15d6 ou 17d6 de dano de veneno, com drenado 1, drenado 1 ou drenado 2, respectivamente, por 1 rodada.', 'Ingested poison with Fortitude DC 42, a 1-minute onset, and a 6-round maximum duration. Stages deal 13d6, 15d6, or 17d6 poison damage with drained 1, drained 1, or drained 2 respectively, for 1 round.', 'Veneno ingerido con Fortaleza CD 42, latencia de 1 minuto y duración máxima de 6 asaltos. Las etapas infligen 13d6, 15d6 o 17d6 de daño de veneno con drenado 1, drenado 1 o drenado 2 respectivamente, durante 1 asalto.', 'compendio', 19, 6500, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":42,"onset":"1 minute","maximumDuration":"6 rounds","stageDuration":"1 round","stages":["13d6 poison + drained 1","15d6 poison + drained 1","17d6 poison + drained 2"]},"needs_review":false}'::jsonb),
  ('item.pc2.death_takings', 'Lágrimas da Morte', 'Tears of Death', 'Lágrimas de la muerte', 'Veneno ingerido com Fortitude CD 44, latência de 1 minuto e duração máxima de 10 minutos. Estágios: 20d6, 22d6 ou 24d6 de dano de veneno e paralisado por 1 rodada.', 'Ingested poison with Fortitude DC 44, a 1-minute onset, and a 10-minute maximum duration. Stages deal 20d6, 22d6, or 24d6 poison damage and paralyze for 1 round.', 'Veneno ingerido con Fortaleza CD 44, latencia de 1 minuto y duración máxima de 10 minutos. Las etapas infligen 20d6, 22d6 o 24d6 de daño de veneno y paralizan durante 1 asalto.', 'compendio', 20, 12000, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":44,"onset":"1 minute","maximumDuration":"10 minutes","stageDuration":"1 round","stages":["20d6 poison + paralyzed","22d6 poison + paralyzed","24d6 poison + paralyzed"]},"needs_review":false}'::jsonb),
  ('item.pc2.cave_worm_venom', 'Veneno de Vorme da Caverna', 'Cave Worm Venom', 'Veneno de gusano de caverna', 'Veneno de ferimento com Fortitude CD 32 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada e causa 5d6, 6d6 ou 8d6 de veneno, sempre com enfraquecido 2.', 'Injury poison with Fortitude DC 32 and a 6-round maximum duration. Each stage lasts 1 round and deals 5d6, 6d6, or 8d6 poison damage, always with enfeebled 2.', 'Veneno de herida con Fortaleza CD 32 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto e inflige 5d6, 6d6 u 8d6 de veneno, siempre con debilitado 2.', 'compendio', 12, 500, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":32,"maximumDuration":"6 rounds","stageDuration":"1 round","stages":["5d6 poison + enfeebled 2","6d6 poison + enfeebled 2","8d6 poison + enfeebled 2"]},"needs_review":false}'::jsonb),
  ('item.pc2.torpor_wine', 'Vinho de Torpor', 'Torpor Wine', 'Vino de sopor', 'Veneno ingerido com Fortitude CD 32, latência de 1 hora e duração máxima de 7 dias. Os estágios deixam a criatura inconsciente por 1, 2 ou 3 dias; enquanto durar, ela não pode acordar por nenhum meio.', 'Ingested poison with Fortitude DC 32, a 1-hour onset, and a 7-day maximum duration. Stages leave the creature unconscious for 1, 2, or 3 days; while it lasts, the creature cannot awaken by any means.', 'Veneno ingerido con Fortaleza CD 32, latencia de 1 hora y duración máxima de 7 días. Las etapas dejan a la criatura inconsciente durante 1, 2 o 3 días; mientras dure, no puede despertarse por ningún medio.', 'compendio', 12, 325, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":32,"onset":"1 hour","maximumDuration":"7 days","stages":["unconscious 1 day","unconscious 2 days","unconscious 3 days"],"special":"cannot awaken while the poison lasts"},"needs_review":false}'::jsonb),
  ('item.pc2.hemlock', 'Cicuta', 'Hemlock', 'Cicuta', 'Veneno ingerido com Fortitude CD 38, latência de 30 minutos e duração máxima de 60 minutos. Cada estágio dura 10 minutos e causa 16d6/17d6/18d6 de veneno e enfraquecido 2/3/4.', 'Ingested poison with Fortitude DC 38, a 30-minute onset, and a 60-minute maximum duration. Each stage lasts 10 minutes and deals 16d6/17d6/18d6 poison damage with enfeebled 2/3/4.', 'Veneno ingerido con Fortaleza CD 38, latencia de 30 minutos y duración máxima de 60 minutos. Cada etapa dura 10 minutos e inflige 16d6/17d6/18d6 de veneno con debilitado 2/3/4.', 'compendio', 17, 2250, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":38,"onset":"30 minutes","maximumDuration":"60 minutes","stageDuration":"10 minutes","stages":["16d6 poison + enfeebled 2","17d6 poison + enfeebled 3","18d6 poison + enfeebled 4"]},"needs_review":false}'::jsonb),
  ('item.pc2.death_cap_powder', 'Pó de Chapéu-da-Morte', 'Death Cap Powder', 'Polvo de sombrerillo de la muerte', 'Veneno ingerido com Fortitude CD 33, latência de 10 minutos e duração máxima de 6 minutos. Os estágios causam 7d8 de veneno; 9d6 de veneno e enjoado 2; 8d10 de veneno e enjoado 3.', 'Ingested poison with Fortitude DC 33, a 10-minute onset, and a 6-minute maximum duration. Stages deal 7d8 poison; 9d6 poison and sickened 2; 8d10 poison and sickened 3.', 'Veneno ingerido con Fortaleza CD 33, latencia de 10 minutos y duración máxima de 6 minutos. Las etapas infligen 7d8 de veneno; 9d6 de veneno y enfermo 2; 8d10 de veneno y enfermo 3.', 'compendio', 13, 450, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":33,"onset":"10 minutes","maximumDuration":"6 minutes","stageDuration":"1 minute","stages":["7d8 poison","9d6 poison + sickened 2","8d10 poison + sickened 3"]},"needs_review":false}'::jsonb),
  ('item.pc2.kings_sleep', 'Sono do Rei', 'King''s Sleep', 'Sueño del rey', 'Veneno ingerido virulento com Fortitude CD 41 e latência de 1 dia. Cada estágio dura 1 dia e causa drenado 1, drenado 1 ou drenado 2; a condição drenado é cumulativa e não pode ser removida enquanto o veneno durar.', 'Virulent ingested poison with Fortitude DC 41 and a 1-day onset. Each stage lasts 1 day and causes drained 1, drained 1, or drained 2; drained is cumulative and cannot be removed while the poison lasts.', 'Veneno ingerido virulento con Fortaleza CD 41 y latencia de 1 día. Cada etapa dura 1 día y causa drenado 1, drenado 1 o drenado 2; drenado es acumulativo y no puede eliminarse mientras dure el veneno.', 'compendio', 18, 4000, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"usage":null,"effects":[],"mechanics":{"save":"Fortitude","saveDC":41,"onset":"1 day","stageDuration":"1 day","stages":["drained 1","drained 1","drained 2"],"virulent":true,"special":"drained is cumulative and cannot be removed while the poison lasts"},"needs_review":false}'::jsonb),
  ('item.pc2.cerulean_scourge', 'Flagelo Cerúleo', 'Cerulean Scourge', 'Flagelo cerúleo', 'Veneno de contato CD 22; causa dano de veneno, desajeitado e estupefato.', 'Contact poison DC 22; deals poison damage, clumsy, and stupefied.', 'Veneno de contacto CD 22; inflige daño de veneno, torpe y estupefacto.', 'compendio', 16, 1450, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.sulfur_vapors', 'Vapores de Enxofre', 'Sulfur Vapors', 'Vapores de azufre', 'Veneno inalado CD 19; causa dano de veneno, ofuscamento e cegueira.', 'Inhaled poison DC 19; inflicts poison damage, dazzled, and blindness.', 'Veneno inhalado CD 19; causa daño de veneno, deslumbrado y ceguera.', 'compendio', 16, 1500, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.fogged_mind_mist', 'Bruma de Mente Enevoada', 'Fogged Mind Mist', 'Bruma de mente nublada', 'Veneno inalado que prejudica faculdades mentais; CD, dano e progressão devem ser conferidos no livro.', 'Inhaled poison that impairs mental faculties; check the book for DC, damage, and progression.', 'Veneno inhalado que perjudica las facultades mentales; verifica el libro para CD, daño y progresión.', 'compendio', 15, 1000, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.fear_flower_nectar', 'Néctar de Flor do Medo', 'Fearflower Nectar', 'Néctar de flor del miedo', 'Veneno ingerido CD 20; causa amedrontado progressivo, fuga e confusão.', 'Ingested poison DC 20; causes escalating fear, fleeing, and confusion.', 'Veneno ingerido CD 20; causa miedo progresivo, huida y confusión.', 'compendio', 4, 16, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.inert_leg', 'Perna Inerte', 'Inert Leg', 'Pierna inerte', 'Prótese básica que restaura a mobilidade funcional do usuário.', 'Basic prosthetic restoring functional mobility to the wearer.', 'Prótesis básica que restaura la movilidad funcional del usuario.', 'compendio', 4, 15, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.pragardent_resin', 'Resina de Pragardente', 'Pragardent Resin', 'Resina de pragardente', 'Veneno de contato que causa dano persistente; CD e progressão devem ser conferidos na entrada do livro.', 'Contact poison that deals persistent damage; check the book entry for DC and progression.', 'Veneno de contacto que causa daño persistente; verifica la entrada para CD y progresión.', 'compendio', 11, 225, 'L', NULL, ARRAY['Consumível']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.predictable_silver_coin', 'Moeda de Prata Previsível', 'Predictable Silver Coin', 'Moneda de plata predecible', 'Moeda mágica cujo resultado previsível pode ser útil em uma decisão ou aposta.', 'A magic coin with a predictable result that can help with a decision or wager.', 'Moneda mágica con un resultado predecible que puede ayudar en una decisión o apuesta.', 'compendio', 1, 3, 'L', NULL, ARRAY['Mágico']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 307, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.lesser_articulated_wire', 'Fio Articulado Menor', 'Lesser Articulated Wire', 'Alambre articulado menor', 'Fio mágico flexível usado para manipular, prender ou alcançar objetos a distância curta.', 'Flexible magic wire used to manipulate, secure, or reach objects at short range.', 'Alambre mágico flexible para manipular, asegurar o alcanzar objetos a corta distancia.', 'compendio', 3, 45, 'L', NULL, ARRAY['Mágico']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 307, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.alchemists_goggles', 'Óculos de Alquimista', 'Alchemist''s Goggles', 'Gafas de alquimista', 'Óculos investidos que auxiliam a identificar e trabalhar com substâncias alquímicas.', 'Invested goggles that assist with identifying and working with alchemical substances.', 'Gafas investidas que ayudan a identificar y trabajar con sustancias alquímicas.', 'compendio', 4, 100, 'L', NULL, ARRAY['Mágico']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 311, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.predictive_veil', 'Véu Prognóstico', 'Predictive Veil', 'Velo pronóstico', 'Véu focado que concede bônus em Religião e pode alimentar uma magia de revelação uma vez por dia; requer um oráculo.', 'Focused veil that grants a Religion bonus and can fuel a revelation spell once per day; requires an oracle.', 'Velo enfocado que concede un bonificador a Religión y puede alimentar un conjuro de revelación una vez al día; requiere un oráculo.', 'compendio', 10, 1000, 'L', NULL, ARRAY['Mágico']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 311, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
  ('item.pc2.greater_predictive_veil', 'Véu Prognóstico Maior', 'Greater Predictive Veil', 'Velo pronóstico mayor', 'Versão maior do Véu Prognóstico, com bônus aprimorado e ativação adicional; requer um oráculo.', 'Greater version of the Predictive Veil with an improved bonus and additional activation; requires an oracle.', 'Versión mayor del Velo pronóstico, con bonificador mejorado y activación adicional; requiere un oráculo.', 'compendio', 18, 21000, 'L', NULL, ARRAY['Mágico']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 311, '{"usage":null,"effects":[],"needs_review":false}'::jsonb),
